var e={entries:JSON.parse(`{"assign":{"short":"يضع القيمة التي على اليمين في الاسم الذي على اليسار.","simple":"مثل كتابة رقم جديد على صندوق عليه ملصق: ما كان بداخله من قبل يختفي.","deep":"إسناد وليس سؤالًا: المقارنة تكون بـ <code>==</code>. في تعريف مثل <code>uint8_t r = 0;</code> يعطي <code>=</code> المتغيّر قيمته الأولى (التهيئة)."},"arithmetic":{"short":"الجمع والطرح والقسمة، مثل الآلة الحاسبة.","simple":"حساب المدرسة، مع مفاجأة واحدة: قسمة عددين صحيحين تُسقط الباقي، فنتيجة <code>7 / 2</code> هي <code>3</code>.","deep":"القسمة الصحيحة تقتطع الناتج نحو الصفر؛ اكتب <code>7 / 2.0f</code> لتحصل على <code>3.5</code>. الأنواع الصغيرة مثل <code>uint8_t</code> تُرقّى إلى <code>int</code> قبل الحساب، فلا يمكن أن يفيض <code>pos * 3</code> إلا عند تخزينه من جديد."},"modulo":{"short":"الباقي بعد القسمة: نتيجة <code>7 % 3</code> هي <code>1</code>.","simple":"مثل وجه الساعة: إذا تجاوزت 12 بدأت العدّ من 1 مرة أخرى. لذلك يناسب <code>%</code> الأشياء التي تدور وتتكرر.","deep":"يعمل مع الأعداد الصحيحة فقط (استخدم <code>fmodf</code> مع الأعداد العشرية). إذا كان الطرف الأيسر سالبًا فالنتيجة سالبة أيضًا، فنتيجة <code>-1 % 6</code> هي <code>-1</code> وليست <code>5</code>."},"compound-assign":{"short":"اختصار يحدّث المتغيّر باستخدام قيمته نفسها: <code>x += 5</code> تعني <code>x = x + 5</code>.","simple":"مثل إضافة المزيد إلى جرّة: لا تفرغها ثم تملؤها، بل تضيف قليلًا فقط.","deep":"يُقيَّم الطرف الأيسر مرة واحدة، وهذا مهم عندما يكون مثل <code>buf_[i++]</code>. تُحوَّل النتيجة إلى نوع المتغيّر، فيلتف <code>uint8_t</code> بهدوء بعد 255."},"increment":{"short":"يزيد المتغيّر بمقدار واحد (<code>++</code>) أو ينقصه بمقدار واحد (<code>--</code>).","simple":"مثل عدّاد يدوي تضغط عليه: ضغطة واحدة تعني واحدًا إضافيًا.","deep":"<code>i++</code> يُرجع القيمة القديمة ثم يضيف واحدًا؛ أما <code>++i</code> فيضيف أولًا. في حلقة <code>for</code> وحده يتصرفان بالطريقة نفسها. المتغيّر <code>uint8_t hue</code> (بلا إشارة) يلتف من 255 إلى 0، وهذا ما يعتمد عليه قوس قزح في الدرس 01."},"compare":{"short":"تقارن قيمتين وتجيب بـ <code>true</code> أو <code>false</code>؛ وبعد اسم النوع تحيط علامتا &lt; &gt; بنوع بدل ذلك.","simple":"أسئلة جوابها نعم أو لا: هل هما متساويان؟ هل هذا أصغر؟ انتبه إلى <code>==</code> المزدوجة: علامة <code>=</code> واحدة ستغيّر القيمة بدل أن تسأل.","deep":"مقارنة قيمة ذات إشارة بقيمة بلا إشارة تحوّل الطرف ذا الإشارة إلى بلا إشارة، فتكون <code>-1 &lt; 1u</code> خاطئة؛ والمترجم يحذّر من ذلك. في <code>std::vector&lt;Card&gt;</code> أو <code>static_cast&lt;int&gt;</code> تكون الأقواس الزاوية أقواس قوالب وليست مقارنات."},"logic":{"short":"تجمع إجابات نعم/لا: <code>&amp;&amp;</code> تعني «و»، و<code>||</code> تعني «أو»، و<code>!</code> تعني «ليس».","simple":"«إذا كانت السماء تمطر <b>و</b> أنا في الخارج، افتح المظلة.» والعلامة <code>!</code> تقلب الجواب: لا تمطر.","deep":"دارة مختصرة: <code>a &amp;&amp; b</code> لا تنظر إلى <code>b</code> أبدًا إذا كانت <code>a</code> خاطئة، ولهذا فإن <code>queue_ &amp;&amp; xQueueReceive(queue_, ...)</code> آمنة مع طابور فارغ (null). بعد نوع (<code>T &amp;&amp;</code>) تعني علامتا & المزدوجتان مرجعًا قابلًا للنقل."},"ternary":{"short":"if/else في سطر واحد تختار قيمة: <code>test ? this : that</code>.","simple":"«هل شاشة HUD مفعّلة؟ إذن قل on، وإلا قل off.» سؤال له جوابان محتملان.","deep":"يجب أن يكون الفرعان قابلين للتحويل إلى نوع مشترك واحد. يُقيَّم الفرع المختار فقط، فمن الآمن استخدامه لحماية قسمة أو مؤشّر."},"shift":{"short":"تزحزح بتّات العدد إلى اليسار أو اليمين؛ خطوة واحدة إلى اليسار تضاعفه، وخطوة إلى اليمين تنصّفه.","simple":"مثل تحريك أرقام عدد على صف من مفاتيح الإضاءة: يتزحزح كل شيء ويدخل صفر جديد في النهاية.","deep":"تُستخدم لتجميع البايتات وفكّها: <code>(r &amp; 0xF8) &lt;&lt; 8</code> تضع الأحمر في أعلى 5 بتّات من لون RGB565. الإزاحة بعرض النوع أو أكثر سلوك غير معرَّف."},"bit-ops":{"short":"تعمل على البتّات المفردة في العدد: <code>|</code> تضبط البتّات، و<code>^</code> تقلبها، و<code>~</code> تعكسها كلها.","simple":"تخيّل العدد صفًّا من 8 أو 16 أو 32 مفتاح إضاءة. تقلب هذه العوامل مفاتيح مختارة دون أن تمسّ الباقي.","deep":"<code>flags |= bit</code> تشغّل بتًّا، و<code>flags &amp;= ~bit</code> تطفئه، و<code>flags ^= bit</code> تبدّله. برامج تشغيل المسجّلات مثل MFRC522 عندنا تعتمد على هذه. وتعيد ArduinoJson استخدام <code>|</code> لقيمة افتراضية: <code>in[\\"type\\"] | \\"\\"</code>."},"scope":{"short":"تصل إلى داخل فضاء أسماء أو صنف أو enum لإيجاد اسم: <code>std::min</code> هي <code>min</code> الموجودة في <code>std</code>.","simple":"مثل العنوان: <i>لندن::شارع بيكر</i>. يمكن أن يتشارك شارعان في الاسم ما داما في مدينتين مختلفتين.","deep":"معامل تحديد النطاق. <code>Button::Event::Click</code> ينزل مستويين؛ وبدء الاسم بـ <code>::</code> (كما في <code>::ble::activity()</code>) يبدأ من فضاء الأسماء العام، فلا يمكن لاسم محلي أن يحجبه."},"arrow":{"short":"يستخدم عضوًا من الشيء الذي يشير إليه المؤشّر: <code>p->x</code> تساوي <code>(*p).x</code>.","simple":"النقطة (<code>.</code>) تخاطب كائنًا تمسكه بيدك؛ والسهم يخاطب كائنًا لا تملك إلا عنوانه.","deep":"الوصول إلى عضو عبر مؤشّر. معالجات الويب تستلم <code>AsyncWebServerRequest *req</code>، فتكتب <code>req->send(...)</code>. اتّباع <code>nullptr</code> يُسقط ESP32 بخطأ LoadProhibited أو StoreProhibited، لذا تُفحص المؤشّرات أولًا."},"maths":{"short":"دوال مساعدة للرياضيات من مكتبة C: الجيب وجيب التمام والجذر التربيعي والتقريب والقيمة المطلقة وغيرها.","simple":"أزرار الآلة الحاسبة العلمية، جاهزة للاستخدام في الكود. الزوايا بالراديان: الدورة الكاملة نحو 6.283.","deep":"نسخ <code>f</code> (<code>sinf</code> و<code>sqrtf</code>) تعمل على <code>float</code> الذي تعالجه وحدة الفاصلة العائمة FPU في ESP32-S3 بسرعة؛ أما نسخ <code>double</code> فتعمل برمجيًا وهي أبطأ بعدة مرات. و<code>lroundf</code> تقرّب إلى أقرب عدد صحيح."},"snprintf":{"short":"تبني نصًّا من قالب وقيم، داخل صندوق ذي حجم ثابت.","simple":"استمارة ذات فراغات: <code>\\"%d/%d\\"</code> فيها فراغان، والأرقام التي تمرّرها تملؤهما بالترتيب.","deep":"<code>snprintf(buf, sizeof(buf), fmt, ...)</code> لا تكتب أبدًا خارج المخزن المؤقت وتُنهي النص دائمًا بـ <code>'\\\\0'</code>؛ والنص الأطول يُقتطع. رموز <code>%</code> نفسها في <code>Serial.printf</code>: <code>%d</code> للعدد الصحيح int، و<code>%u</code> بلا إشارة، و<code>%lu</code> unsigned long، و<code>%.1f</code> عشري، و<code>%s</code> نص، و<code>%02X</code> ست عشري."},"void":{"short":"تعني «لا شيء»: دالة <code>void</code> تؤدي عملها ولا تُرجع أي قيمة.","simple":"مثل جرس الباب: تضغطه فيحدث شيء، لكنه لا يعطيك شيئًا تمسكه.","deep":"كنوع إرجاع تعني بلا نتيجة. أما <code>void *</code> فمؤشّر إلى ذاكرة من نوع مجهول، كما في <code>void *arg</code> الذي تستلمه مهام FreeRTOS ومعالجات المقاطعات؛ ويجب تحويله إلى نوعه قبل الاستخدام."},"bool":{"short":"قيمة نعم/لا: إما <code>true</code> أو <code>false</code>.","simple":"مفتاح إضاءة: مشغّل أو مطفأ، ولا شيء بينهما.","deep":"يشغل بايتًا واحدًا. تتحول الأعداد والمؤشّرات إلى <code>bool</code> تلقائيًا (الصفر و<code>nullptr</code> خاطئان)، ولهذا تعمل <code>if (buf_)</code>. و<code>boolean</code> في Arduino هو النوع نفسه."},"true-false":{"short":"القيمتان اللتان يمكن أن يحملهما <code>bool</code>.","simple":"نعم ولا، مكتوبتان بالطريقة التي يفهمها المترجم.","deep":"كلمتان مفتاحيتان من النوع <code>bool</code>؛ وعند تحويلهما إلى أعداد تصبحان 1 و0. ويستخدم FreeRTOS <code>pdTRUE</code>/<code>pdFALSE</code> الخاصتين به للفكرة نفسها."},"int":{"short":"عدد صحيح يمكن أن يكون سالبًا، وهو الافتراضي اليومي للعدّ.","simple":"صندوق للأعداد الصحيحة مثل -3 و0 و42. لا كسور فيه.","deep":"في ESP32 يبلغ <code>int</code> 32 بتًّا: من نحو -2.1 مليار إلى +2.1 مليار. يختلف حجمه بين الرقاقات (16 بتًّا في Arduino Uno)، ولهذا يفضّل كود العتاد غالبًا <code>int32_t</code> وأخواتها التي تصرّح بحجمها."},"long":{"short":"نوع عدد صحيح لا يقل حجمه عن <code>int</code>؛ وفي ESP32 كلاهما 32 بتًّا.","simple":"صندوق آخر للأعداد الصحيحة. على هذه الرقاقة يحمل ما يحمله <code>int</code> تمامًا.","deep":"<code>long</code> هو 32 بتًّا في Xtensa ESP32، و<code>long long</code> هو 64. تُرجع <code>millis()</code> قيمة <code>unsigned long</code>، فتحتاج طباعتها إلى <code>%lu</code>؛ وغالبًا يحوّل الكود بـ <code>static_cast&lt;unsigned long&gt;</code> لتطابق ذلك تمامًا."},"unsigned":{"short":"عدد صحيح لا ينزل تحت الصفر، فيصل إلى ضعف الارتفاع.","simple":"مثل عدّاد المسافة في السيارة: يعدّ صعودًا من 0 فقط، وبعد آخر خانة يعود إلى 0.","deep":"الحساب بلا إشارة يلتف بدل أن يفيض: <code>0u - 1</code> هي أكبر قيمة. وهذا الالتفاف هو بالضبط سبب استمرار عمل <code>now - last >= interval</code> عندما تلتف <code>millis()</code>. و<code>unsigned(x)</code> تحويل سريع، مفيد مع <code>%u</code> في printf."},"float":{"short":"عدد له فاصلة عشرية، مثل <code>3.14</code> أو <code>-0.5</code>.","simple":"مسطرة بعلامات دقيقة: جيدة للقياسات، لكن تتسلل إليها أخطاء تقريب صغيرة، فلا تختبر أبدًا تساوي عددين عشريين تساويًا تامًّا.","deep":"32 بتًّا، نحو 7 أرقام معنوية. في ESP32-S3 وحدة FPU أحادية الدقة، فحساب <code>float</code> سريع؛ اكتب الثوابت بالشكل <code>0.5f</code> حتى لا يتحول المترجم إلى <code>double</code> البطيء."},"double":{"short":"عدد عشري بدقة تبلغ نحو ضعف دقة <code>float</code>.","simple":"المسطرة نفسها مثل <code>float</code>، بعلامات أدق، لكنها أبطأ في القراءة على هذه الرقاقة.","deep":"64 بتًّا، نحو 15 رقمًا معنويًا. وحدة FPU في ESP32-S3 تدعم الدقة الأحادية فقط، فيُنفَّذ <code>double</code> برمجيًا: لا بأس به لحساب عَرَضي، لكنه بطيء جدًا لكل بكسل أو عيّنة صوت."},"char":{"short":"حرف واحد من النص، مخزَّن كعدد صغير؛ أما <code>const char *</code> فهو نص كامل.","simple":"قطعة حرف واحدة من لعبة كلمات. صُفّ القطع، وأنهِها بقطعة توقّف غير مرئية <code>'\\\\0'</code>، فتحصل على كلمة.","deep":"بايت واحد. سلسلة C هي مصفوفة من <code>char</code> تنتهي بـ <code>'\\\\0'</code>؛ و<code>char text[32]</code> تتّسع لـ 31 حرفًا. و<code>\\"hello\\"</code> هو <code>const char *</code> إلى نص محفوظ في الفلاش، بينما <code>'h'</code> (بعلامتي اقتباس مفردتين) هو <code>char</code> واحد."},"size-t":{"short":"عدد صحيح بلا إشارة مصنوع لأحجام الأشياء وأعدادها في الذاكرة.","simple":"الرقم على شريط القياس للذاكرة: كم بايتًا وكم عنصرًا. لا يمكن أن يكون سالبًا.","deep":"32 بتًّا في ESP32، وهو النوع الذي يُرجعه <code>sizeof</code> ويستلمه <code>malloc</code>. اطبعه بـ <code>%u</code> بعد تحويل، أو بـ <code>%zu</code>."},"uint8-t":{"short":"عدد صحيح من 0 إلى 255: بايت واحد بالضبط.","simple":"أصغر صندوق: بايت واحد، ثمانية مفاتيح تشغيل/إيقاف. مثالي لقناة لون أو رقم طرف أو سطوع.","deep":"<code>u</code> = بلا إشارة، و<code>int</code>، و<code>8</code> بتّات، و<code>_t</code> = نوع. معرَّف في <code>&lt;stdint.h&gt;</code> فحجمه واحد على كل رقاقة. و<code>byte</code> في Arduino هو النوع نفسه. وبعد 255 يلتف إلى 0."},"uint16-t":{"short":"عدد صحيح من 0 إلى 65 535: بايتان.","simple":"صندوق بضعف حجم البايت. كل ألوان الشاشة في هذه المختبرات تتّسع فيه.","deep":"بلا إشارة، 16 بتًّا. تتكلم ST7789 بصيغة RGB565: 5 بتّات للأحمر و6 للأخضر و5 للأزرق مجموعة في <code>uint16_t</code> واحد. ويُستخدم أيضًا لمقابض BLE ومعرّفات UUID ذات 16 بتًّا."},"uint32-t":{"short":"عدد صحيح من 0 إلى نحو 4.29 مليار: أربعة بايتات.","simple":"صندوق كبير للأعداد الكبيرة، مثل المللي ثانية منذ بدء تشغيل اللوحة.","deep":"بلا إشارة، 32 بتًّا: حجم الكلمة الطبيعي في ESP32، فقراءته وكتابته تعليمة واحدة. الأزمنة الناتجة من <code>millis()</code> تُحفظ فيه وتلتف بعد نحو 49.7 يومًا."},"uint64-t":{"short":"عدد صحيح ضخم، من 0 إلى نحو 18 كوينتيليون: ثمانية بايتات.","simple":"صندوق كبير لدرجة أنه لا يمتلئ عمليًا. يتّسع بسهولة لعنوان MAC الخاص بالرقاقة ذي 48 بتًّا.","deep":"بلا إشارة، 64 بتًّا. في وحدة معالجة 32 بتًّا تحتاج كل عملية إلى عدة تعليمات، وقراءة قيمة مشتركة بين مقاطعة والكود الرئيسي ليست خطوة واحدة، لذا تُبقي المختبرات الطوابع الزمنية المشتركة بحجم 32 بتًّا."},"int8-t":{"short":"عدد صحيح صغير من -128 إلى 127: بايت واحد يمكن أن يكون سالبًا.","simple":"صندوق من بايت واحد فيه مكان لعلامة الناقص. جيد لأشياء مثل قوة إشارة Wi-Fi بوحدة dBm.","deep":"بإشارة، 8 بتّات، مُتمّم الاثنين. تُبلَّغ قدرة إرسال BLE وقيم RSSI على شكل <code>int8_t</code>."},"int16-t":{"short":"عدد صحيح من -32 768 إلى 32 767: بايتان يمكن أن يكونا سالبين.","simple":"صندوق من بايتين بعلامة ناقص. تستخدمه إحداثيات الشاشة، فيمكن للأشكال أن تبدأ خارج الحافة بقليل.","deep":"بإشارة، 16 بتًّا. تأخذ Adafruit GFX النوع <code>int16_t</code> للإحداثيين x وy والعرض والارتفاع، وعيّنات الصوت ذات 16 بتًّا من الميكروفون هي <code>int16_t</code> أيضًا."},"int32-t":{"short":"عدد صحيح من نحو -2.1 مليار إلى +2.1 مليار: أربعة بايتات يمكن أن تكون سالبة.","simple":"الصندوق نفسه مثل <code>int</code> على هذه الرقاقة، لكن اسمه يَعِد بالحجم على كل رقاقة.","deep":"بإشارة، 32 بتًّا. يرسل الميكروفون INMP441 عيّنات من 24 بتًّا داخل فتحات I2S من 32 بتًّا، تُقرأ على شكل <code>int32_t</code> ثم تُزاح إلى الأسفل."},"int64-t":{"short":"عدد صحيح ضخم يمكن أن يكون سالبًا: ثمانية بايتات.","simple":"صندوق لا ينفد أبدًا لساعات تعدّ الميكروثواني.","deep":"بإشارة، 64 بتًّا. تُرجع <code>esp_timer_get_time()</code> قيمة <code>int64_t</code> بالميكروثانية منذ الإقلاع، وسيستغرق فيضانها نحو 292 000 سنة."},"string-class":{"short":"نوع النص في Arduino: قطعة نص يمكن أن تكبر وتصغر ويمكن البحث فيها.","simple":"صفحة دفتر مطّاطة للكلمات: أضف إليها، واقتطع منها، وابحث عن كلمة، دون أن تعدّ الحروف بنفسك.","deep":"يحتفظ بحروفه في الكومة heap (القصيرة منها داخله)، لذا فتكرار <code>+</code> في حلقة مشغولة يُرهق الذاكرة. تستخدم المختبرات <code>String</code> لأوامر المنفذ التسلسلي وردود الويب، ومصفوفات <code>char</code> ثابتة حيث تهم السرعة أو المقاطعات. و<code>String(42)</code> تحوّل عددًا إلى نص."},"auto":{"short":"يتيح للمترجم استنتاج النوع من القيمة التي تعطيها.","simple":"مثل أن تقول «ضعه في صندوق بالحجم المناسب» بدل أن تسمّي الصندوق.","deep":"النوع يبقى ثابتًا وقت الترجمة، وليس ديناميكيًا. <code>auto *self = static_cast&lt;Button *&gt;(arg);</code> يتجنب كتابة <code>Button</code> مرتين؛ و<code>auto</code> هي أيضًا طريقة تخزين اللامدا، لأن نوعها بلا اسم."},"nullptr":{"short":"مؤشّر لا يشير إلى شيء.","simple":"ملصق عنوان فارغ: لا بيت يُزار، فتحقق قبل أن تذهب.","deep":"ثابت المؤشّر الفارغ الآمن الأنواع (C++11)، وهو يحلّ محل <code>NULL</code> و<code>0</code>. دوال التخصيص مثل <code>heap_caps_malloc</code> تُرجعه عند الفشل، وكثير من استدعاءات ESP-IDF تأخذه بمعنى «لا أحتاج هذا»."},"if":{"short":"ينفّذ الكتلة التالية فقط عندما يكون الاختبار بين القوسين صحيحًا.","simple":"«إذا كانت السماء تمطر، خذ مظلة.» وعندما لا تمطر تُتخطى خطوة المظلة.","deep":"يُحوَّل الشرط إلى <code>bool</code>، فتعمل الأعداد والمؤشّرات مباشرة. والتصريح داخل الاختبار (<code>if (DeserializationError e = deserializeJson(...))</code>) يُبقي المتغيّر داخل if."},"else":{"short":"المسار الآخر: يعمل عندما يكون اختبار <code>if</code> خاطئًا.","simple":"«...وإلا فالبس نظارة شمسية.» يحدث مسار واحد فقط من المسارين.","deep":"<code>else if</code> هي مجرد <code>else</code> كتلتها <code>if</code> أخرى، فتُفحص السلاسل من الأعلى إلى الأسفل وتتوقف عند أول اختبار صحيح."},"for":{"short":"تكرّر كتلة عددًا محدّدًا من المرات، أو مرة لكل عنصر في قائمة.","simple":"«لكل بايت من البايتات الستة، اطبعه.» ابدأ من 0، وتحقق أنك لم تنتهِ، ونفّذ العمل، وعُدّ للأعلى، وكرّر.","deep":"<code>for (init; test; step)</code>. الصيغة النطاقية <code>for (const auto &amp;card : cards)</code> تزور كل عنصر في مصفوفة أو حاوية دون فهرس."},"while":{"short":"تكرّر كتلة ما دام اختبارها صحيحًا.","simple":"«ما دام هناك رسائل في صندوق البريد، أخرج واحدة.» وعندما يفرغ، توقف.","deep":"يُجرى الاختبار قبل كل جولة، فقد لا يُنفَّذ الجسم أبدًا. و<code>while</code> لا تنتهي داخل <code>loop()</code> تُجوّع بقية البرنامج؛ تقرأ المختبرات الإدخال بـ <code>while (Serial.available())</code> التي تنتهي حالما يفرغ المخزن المؤقت."},"do-while":{"short":"مثل <code>while</code>، لكن الكتلة تُنفَّذ دائمًا مرة واحدة على الأقل قبل الاختبار.","simple":"تذوّق الحساء، ثم قرّر هل يحتاج إلى مزيد من الملح. أنت تتذوق دائمًا أولًا.","deep":"يأتي الاختبار بعد الجسم ويحتاج إلى فاصلة منقوطة: <code>do { ... } while (cond);</code>. مفيد لـ «اختر قيمة عشوائية حتى تكون جيدة»."},"switch":{"short":"تختار مسارًا من عدة مسارات بمقارنة قيمة بخيارات ثابتة.","simple":"لوحة مصعد: تضغط 3 فتذهب إلى الطابق 3. كل <code>case</code> هو زر واحد.","deep":"يعمل مع الأعداد الصحيحة وأنواع enum، لا مع النص. ينتقل التنفيذ إلى الحالة التالية ما لم تكتب <code>break</code> أو <code>return</code>. ومع <code>enum class</code> يحذّرك المترجم من الحالات التي نسيتها."},"case":{"short":"خيار واحد داخل <code>switch</code>: الكود الذي يعمل عندما تطابق القيمة.","simple":"زر واحد في لوحة المصعد، ومكتوب بجانبه رقم الطابق.","deep":"يجب أن تكون التسمية ثابتًا وقت الترجمة. يمكن لعدة تسميات أن تتشارك جسمًا واحدًا بتكديسها؛ والجسم الذي لا يحتوي <code>break</code> يكمل إلى الحالة التالية."},"default":{"short":"داخل <code>switch</code>، المسار الذي يُتّبع عندما لا تطابق أي <code>case</code>.","simple":"زر «أي شيء آخر».","deep":"اختياري ويمكن وضعه في أي مكان داخل switch. وفي الصنف تعني <code>= default</code> شيئًا آخر: اطلب من المترجم أن يكتب هذا المُنشئ أو المعامل نيابةً عنك."},"break":{"short":"يغادر الحلقة الحالية أو <code>switch</code> فورًا.","simple":"مخرج طوارئ: توقف عن الدوران وتابع بعد الحلقة.","deep":"يغادر الحلقة أو switch الأعمق فقط. داخل switch موجود في حلقة، يغادر <code>break</code> الـ switch لا الحلقة."},"continue":{"short":"يتخطى بقية هذه الجولة من الحلقة ويبدأ الجولة التالية.","simple":"«هذه الرسالة ليست لي: ضعها جانبًا وافتح التالية.»","deep":"في حلقة <code>for</code> تُنفَّذ الخطوة (<code>i++</code>) قبل الاختبار التالي مع ذلك. يُستخدم غالبًا لتخطي البيانات السيئة مبكرًا بدل تعشيش <code>if</code>."},"return":{"short":"تُنهي الدالة الآن، وتُرجع قيمة إلى من استدعاها إن أردت.","simple":"تسليم الواجب المنتهي: العمل انتهى وهذه هي الإجابة.","deep":"في دالة <code>void</code> تغادر <code>return;</code> المجرّدة مبكرًا فقط، وهي طريقة شائعة للخروج عند إدخال سيئ (جملة حارس). تُتلَف المتغيّرات المحلية عند الخروج، وبهذه الطريقة يفتح <code>std::lock_guard</code> القفل."},"setup-loop":{"short":"كل برنامج Arduino فيه هاتان الدالتان: تعمل <code>setup()</code> مرة واحدة عند التشغيل، ثم تعمل <code>loop()</code> إلى الأبد.","simple":"فتح محل: تفتح <code>setup()</code> الباب وتشعل الأضواء مرة واحدة؛ وتخدم <code>loop()</code> زبونًا بعد زبون حتى وقت الإغلاق (إطفاء الطاقة).","deep":"تبدأ <code>main</code> في نواة Arduino مهمة FreeRTOS (اسمها \\"loopTask\\" على النواة 1 بمكدّس 8 KB افتراضيًا) تستدعي <code>setup()</code> ثم <code>loop()</code> مرارًا. أبقِ <code>loop()</code> سريعة وغير حاجبة: افحص <code>millis()</code> بدل <code>delay()</code> الطويلة. و<code>lab.loop()</code> في المختبر هو عمل الغلاف في كل جولة."},"lambda":{"short":"دالة صغيرة تُكتب حيث تُحتاج، وغالبًا تُمرَّر إلى دالة أخرى لتستدعيها لاحقًا.","simple":"ورقة لاصقة بتعليمات تسلّمها لشخص: «عندما يصل طلب إلى / افعل هذا».","deep":"<code>[capture](params) { body }</code>. قائمة الالتقاط تقول ما يمكن استخدامه مما حولها: <code>[this]</code> الكائن الحالي، و<code>[&amp;]</code> كل شيء بالمرجع، و<code>[]</code> لا شيء. مسارات الويب وأحداث Wi-Fi والفرز كلها تأخذ لامدا هنا."},"variadic":{"short":"تعني «أي عدد من المعاملات الإضافية»، مثل القيم التي يحتاجها قالب printf.","simple":"«...وهكذا»: تأخذ الدالة من الإضافات بقدر ما تعطيها.","deep":"في <code>void warn(const char *fmt, ...)</code> تُقرأ الإضافات بـ <code>va_list</code> وتُمرَّر إلى <code>vsnprintf</code>؛ والسمة <code>[[gnu::format(printf, 2, 3)]]</code> تتيح للمترجم أن يفحصها مقابل القالب. وفي الماكرو، تلصقها <code>__VA_ARGS__</code>."},"inline":{"short":"تسمح بتعريف دالة أو متغيّر في ملف ترويسة تضمّه ملفات كثيرة.","simple":"وصفة مطبوعة في كل كتاب طبخ يحتاجها: يتفق المطبخ على أنها كلها وصفة واحدة لا منافسات.","deep":"مهمتها الحقيقية هي قاعدة التعريف الواحد: يمكن لدالة <code>inline</code> في ملف <code>.h</code> أن تظهر في ملفات <code>.cpp</code> كثيرة دون تعارض في الرابط. أما هل يُدمَج الاستدعاء فعلًا فيعود للمحسِّن. والدوال <code>constexpr</code> والدوال المعرَّفة داخل صنف هي inline تلقائيًا."},"operator":{"short":"تعلّم النوع ما يجب أن يفعله رمز مثل <code>==</code> أو <code>[]</code> أو <code>+</code> معه.","simple":"مثل تعليم قطعة لعبة جديدة القواعد الموجودة: الآن تعمل <code>a == b</code> مع نوعك الخاص أيضًا.","deep":"<code>bool operator==(const Uid &amp;o) const</code> هي مجرد دالة باسم خاص؛ و<code>explicit operator bool()</code> تتيح اختبار كائن داخل <code>if</code>."},"noexcept":{"short":"وعد بأن الدالة لن ترمي استثناءً أبدًا.","simple":"لافتة على الباب: «لا مفاجآت هنا».","deep":"إذا رمت مع ذلك، فإن <code>std::terminate</code> تُنهي البرنامج. تستخدمها الحاويات القياسية لتقرر هل نقل عنصر آمن. يُبنى Arduino-ESP32 والاستثناءات متاحة، لكن المختبرات لا ترمي استثناءات أبدًا."},"override":{"short":"تتيح <code>virtual</code> لصنف ابن أن يستبدل دالة؛ وتعلّم <code>override</code> الاستبدال.","simple":"استمارة بفراغ: تترك المكتبة «كيف يُرسم بكسل واحد» لتملأه أنت، وتقول <code>override</code> «هذا جوابي لذلك الفراغ».","deep":"تمرّ الاستدعاءات عبر جدول مؤشّرات دوال (vtable)، فينتهي كود <code>Adafruit_GFX</code> إلى استدعاء <code>FrameBuffer::drawPixel</code> الخاصة بنا. وتجعل <code>override</code> المترجم يتحقق من وجود virtual مطابقة. وتعمل ردود NimBLE مثل <code>onConnect</code> بالطريقة نفسها."},"explicit":{"short":"تمنع المترجم من تحويل نوع إلى آخر بصمت عبر مُنشئ.","simple":"«اسأل أولًا»: لن يصير الرقم <code>Button</code> لمجرد أن <code>Button</code> يمكن بناؤه من رقم.","deep":"من دونها يكون المُنشئ ذو المعامل الواحد تحويلًا ضمنيًا، فيمكن استدعاء دالة تأخذ <code>BootButton</code> برقم عادي. وتُستخدم أيضًا مع <code>operator bool</code>."},"constructor":{"short":"دالة خاصة باسم الصنف نفسه تهيّئ كائنًا جديدًا.","simple":"تعليمات التجميع التي تعمل مرة واحدة عندما يخرج شيء جديد من العلبة.","deep":"بلا نوع إرجاع. القائمة بعد <code>:</code> (<code>: pin_(pin), name_(name)</code>) تملأ الأعضاء قبل تنفيذ الجسم، بترتيب تصريحها. ودالة الهدم <code>~Name()</code> تعمل عندما يزول الكائن، مثل <code>FrameBuffer</code> وهو يحرّر بكسلاته."},"address-reference":{"short":"لها ثلاث مهام: بعد النوع تصنع مرجعًا (اسمًا آخر)، وقبل متغيّر تأخذ عنوانه، وبين عددين هي AND على مستوى البتّات.","simple":"المرجع لقب: <code>uint8_t &amp;r</code> تتيح لدالة أن تكتب مباشرة في صندوقك. و<code>&amp;x</code> هو عنوان شارع الصندوق. و<code>a &amp; b</code> تُبقي فقط البتّات المشغّلة في كليهما.","deep":"<code>T &amp;</code> ترتبط بكائن موجود ولا يمكن أن تكون فارغة أو يُعاد توجيهها؛ و<code>const T &amp;</code> تمرّر الأشياء الكبيرة دون نسخ. و<code>&amp;lock_</code> تعطي <code>portMUX_TYPE *</code>. و<code>x &amp; 0xFF</code> تقنّع البايت المنخفض."},"pointer":{"short":"لها ثلاث مهام: بعد النوع تصرّح بمؤشّر، وقبل مؤشّر تتبعه، وبين عددين تضرب.","simple":"المؤشّر ورقة صغيرة مكتوب عليها عنوان. و<code>*p</code> تعني «اذهب إلى ذلك العنوان واستخدم ما هناك». وبين عددين هي ببساطة ضرب.","deep":"المؤشّرات 4 بايتات في ESP32. <code>uint16_t *buf_</code> تحمل مكان بداية البكسلات؛ و<code>buf_[i]</code> تساوي <code>*(buf_ + i)</code>. و<code>const char *</code> مؤشّر إلى نص يمكنك قراءته لا تغييره."},"array":{"short":"صف ثابت من قيم من النوع نفسه، مرقّمة من 0.","simple":"علبة بيض: عدد ثابت من الخانات كلها بالشكل نفسه. أرقام الخانات تبدأ من 0، فعلبة من 6 خانات خاناتها من 0 إلى 5.","deep":"<code>char text[32]</code> تحجز 32 بايتًا هناك مباشرة، دون الكومة heap. لا شيء يفحص الفهرس، فكتابة <code>text[32]</code> تدوس بصمت على ما يجاورها؛ و<code>sizeof(text)</code> تعطي الحجم الكامل بالبايت، ولهذا تمرّره استدعاءات المخازن المؤقتة."},"const":{"short":"تعلّم قيمة على أنها للقراءة فقط: متى ضُبطت لا يجوز للكود تغييرها.","simple":"ملصق مكتوب بالحبر لا بالرصاص.","deep":"بخلاف <code>constexpr</code> يمكن أن تأتي القيمة من كود يُنفَّذ (<code>const uint32_t now = millis();</code>). وبعد أقواس دالة عضو، تعد <code>const</code> بأن الدالة لن تغيّر الكائن. و<code>const char *p</code> تحمي النص؛ و<code>char *const p</code> تحمي المؤشّر."},"static":{"short":"تُبقي متغيّرًا حيًّا طوال البرنامج، أو تتشارك نسخة واحدة بين كل كائنات الصنف.","simple":"داخل دالة هي دفتر يبقى على المكتب بين الزيارات، فتتذكر <code>loop()</code> قيمتها الأخيرة.","deep":"لها ثلاثة معانٍ. المتغيّر المحلي <code>static</code> يُنشأ مرة واحدة ويبقى بين الاستدعاءات. والعضو <code>static</code> ينتمي إلى الصنف لا إلى كل كائن (معالج المقاطعة <code>onEdge</code> هو static ويحصل على الكائن عبر <code>arg</code>). وعلى مستوى الملف تجعل الاسم خاصًّا بذلك الملف."},"volatile":{"short":"تخبر المترجم أن هذه القيمة قد تتغير من وراء ظهره، فيجب أن يعيد قراءتها في كل مرة.","simple":"صندوق بريد قد يمتلئ وأنت لا تنظر: عليك أن تذهب وتفحصه، لا أن تفترض أنه ما زال فارغًا.","deep":"ضرورية للمتغيّرات التي تكتبها مقاطعة ويقرؤها الكود العادي. وهي <b>ليست</b> قفلًا وليست ذرّية: يمكن أن تتمزق قيمة 64 بتًّا. وللبيانات المشتركة بين المهام فضّل <code>std::atomic</code> أو mutex أو مقطعًا حرجًا."},"sizeof":{"short":"تخبرك كم بايتًا يشغل نوع أو متغيّر.","simple":"مثل قراءة السعة المطبوعة على جرّة قبل أن تصبّ فيها أي شيء.","deep":"تُحسب وقت الترجمة، فلا تكلّف شيئًا وقت التشغيل. <code>sizeof(text)</code> لمصفوفة هي حجمها الكامل بالبايت، أما لمؤشّر فهي 4 فقط. و<code>sizeof(arr) / sizeof(arr[0])</code> تعدّ العناصر."},"new-delete":{"short":"<code>new</code> تبني كائنًا في الذاكرة الحرّة (الكومة heap)؛ و<code>delete</code> تدمّره وتعيد الذاكرة.","simple":"استئجار وحدة تخزين: <code>new</code> تستأجر واحدة، و<code>delete</code> تسلّم المفتاح. وإن نسيت التسليم ضاع المكان حتى إعادة التشغيل.","deep":"كل <code>new</code> تحتاج إلى <code>delete</code> واحدة بالضبط (و<code>new[]</code> تحتاج <code>delete[]</code>). في ESP32 قد تقع <code>new</code> العادية في ذاكرة RAM الداخلية أو PSRAM بحسب الحجم وإعدادات البناء؛ وللاختيار استخدم <code>heap_caps_malloc</code>. و<code>= delete</code> على دالة تمنعها، كالنسخ مثلًا."},"progmem":{"short":"تطلب أن تبقى البيانات في ذاكرة الفلاش بدل نسخها إلى RAM.","simple":"اترك الكتاب الكبير على رف المكتبة واقرأه هناك بدل تصويره على مكتبك الصغير.","deep":"أساسية في لوحات AVR Arduino؛ وفي ESP32 معرَّفة بلا شيء، لأن بيانات <code>const</code> تبقى أصلًا في فلاش مُخرَّط على الذاكرة. وتُبقى للوضوح وقابلية النقل، كما في صفحة الويب في <code>kPage</code>."},"iram-attr":{"short":"تضع دالة في ذاكرة RAM الداخلية السريعة للرقاقة، لتعمل في اللحظة التي تنطلق فيها مقاطعة.","simple":"إبقاء طفاية الحريق قرب الباب بدل القبو: يجب أن تكون في المتناول فورًا.","deep":"الكود العادي يعمل من الفلاش الخارجي عبر ذاكرة مخبّئية cache، وتُطفأ هذه الذاكرة أثناء الكتابة في الفلاش (NVS وOTA). ومعالج مقاطعة في الفلاش سيُسقط الرقاقة حينها؛ و<code>IRAM_ATTR</code> تُبقيه في IRAM. وكل ما يستدعيه يجب أن يكون في IRAM أيضًا، فأبقِ المعالجات صغيرة جدًا."},"c-strings":{"short":"أدوات C للنص في مصفوفات <code>char</code>: انسخه وقارنه وقِسه.","simple":"العمل بقطع الحروف يدويًا: انسخ كلمة إلى صفك، وقارن صفّين، وعدّ القطع قبل قطعة التوقف.","deep":"<code>strlcpy(dst, src, sizeof(dst))</code> تنسخ بأمان وتنتهي دائمًا بـ <code>'\\\\0'</code>. و<code>strcmp</code> تُرجع 0 عندما يتساوى نصّان (وليس true!)، ولذلك يُكتب <code>strcmp(a, b) == 0</code>. و<code>strlen</code> تعدّ الحروف لا <code>'\\\\0'</code> الأخير."},"memcpy":{"short":"تنسخ كتلة من البايتات الخام أو تملؤها أو تقارنها.","simple":"نقل صينية بيض كاملة دفعة واحدة بدل بيضة بيضة.","deep":"تعمل على البايتات ولا تعرف شيئًا عن الأنواع: الطول دائمًا بالبايت، فاستخدم <code>sizeof</code>. و<code>memcpy</code> يجب ألا تتداخل (استخدم <code>memmove</code>)؛ و<code>memcmp</code> تُرجع 0 عند التساوي. وبهذه الطريقة تُعالج معرّفات UID للبطاقات وحمولات BLE."},"struct":{"short":"تجمع عدة قيم مسمّاة في نوع جديد واحد.","simple":"استمارة بحقول معنونة: لكل Card معرّف UID واسم ولون، وهي تنتقل معًا.","deep":"مطابق لـ <code>class</code> إلا أن الأعضاء <code>public</code> افتراضيًا. تستخدم المختبرات struct للبيانات البسيطة (<code>HttpsResult</code> و<code>Frame</code>) وclass للأشياء ذات السلوك."},"class":{"short":"يعرّف نوعًا جديدًا من الكائنات: البيانات التي يحتفظ بها والأشياء التي يستطيع فعلها.","simple":"مخطط لجهاز: ما الأجزاء بداخله وأي الأزرار على الخارج.","deep":"الأعضاء <code>private</code> افتراضيًا. <code>class FrameBuffer : public Adafruit_GFX</code> يرث كل ما تستطيع سطح رسم GFX فعله. و<code>enum class</code> تعيد استخدام الكلمة لشيء مختلف: enum محصور النطاق."},"enum":{"short":"قائمة خيارات مسمّاة، مثل <code>Click</code> و<code>DoubleClick</code> و<code>LongPress</code>.","simple":"سؤال اختيار من متعدد: يجب أن يكون الجواب أحد الخيارات المطبوعة على الورقة.","deep":"<code>enum class Event { ... }</code> محصور النطاق (يُكتب <code>Event::Click</code>) ولن يتحول إلى <code>int</code> بالخطأ. و<code>: uint8_t</code> تختار نوع التخزين. أما <code>enum</code> العادي فيسرّب أسماءه إلى النطاق المحيط."},"namespace":{"short":"مجلد مسمّى للدوال والأنواع، فلا تتعارض أسماء الأجزاء المختلفة أبدًا.","simple":"ألقاب للكود: يمكن أن يوجد <code>pal::ink</code> و<code>sv::ink</code> معًا، مثل شخصين اسمهما سامي من عائلتين مختلفتين.","deep":"<code>namespace { }</code> بلا اسم يجعل كل ما بداخله خاصًّا بملف <code>.cpp</code> ذاك (ربط داخلي)، كما يفعل الدرس 01 مع دوالّه المساعدة. و<code>using namespace x;</code> تسحب الأسماء إلى الخارج من جديد؛ تجنّبها في الترويسات."},"std":{"short":"فضاء أسماء المكتبة القياسية في C++: <code>std::min</code> و<code>std::vector</code> و<code>std::mutex</code>...","simple":"صندوق الأدوات الذي يأتي مع كل مترجم C++. و<code>std::</code> تقول «خذ هذه الأداة من الصندوق القياسي».","deep":"يأتي Arduino-ESP32 بمكتبة C++ قياسية كاملة (libstdc++ من GCC)، تشمل الحاويات والخوارزميات و<code>&lt;atomic&gt;</code> و<code>&lt;mutex&gt;</code> فوق FreeRTOS. راقب استخدام الكومة: الحاويات تحجز ذاكرة."},"access":{"short":"تقرر من يستطيع استخدام أعضاء الصنف: الجميع، أو الصنف نفسه فقط، أو الصنف وأبناؤه.","simple":"أزرار واجهة المذياع هي <code>public</code>؛ واللوحة الإلكترونية في داخله <code>private</code>.","deep":"يُبقي الصنف بياناته <code>private</code> (هنا بشَرطة سفلية <code>_</code> في النهاية، كما في <code>pin_</code>) ويقدّم دوال <code>public</code>، فيمكنه تغيير داخله دون كسر من يستدعيه. وفي <code>: public Adafruit_GFX</code> تحدد الكلمة كيف تُورَّث أعضاء الأب."},"this":{"short":"داخل دالة عضو، مؤشّر إلى الكائن الذي تعمل عليه الدالة.","simple":"«أنا»: الكائن وهو يشير إلى نفسه.","deep":"تكون ضمنية عادةً (<code>pin_</code> تعني <code>this->pin_</code>). وتُمرَّر صراحةً عندما يحتاج رد نداء بأسلوب C إلى طريق العودة، كما في <code>attachInterruptArg(..., onEdge, this, CHANGE)</code> أو معامل مهمة، وتلتقطها اللامدا بـ <code>[this]</code>."},"using":{"short":"تعطي نوعًا اسمًا أقصر أو أوضح.","simple":"لقب: قل <code>JsonFn</code> بدل النوع الطويل كله في كل مرة.","deep":"<code>using JsonFn = std::function&lt;...&gt;;</code> هي الصيغة الحديثة لـ <code>typedef</code> وتُقرأ من اليسار إلى اليمين. و<code>using namespace std;</code> و<code>using Base::f;</code> استخدامان آخران للكلمة نفسها."},"union":{"short":"عدة أعضاء تتشارك البايتات نفسها، فلا يكون ذا معنى إلا واحد في كل مرة.","simple":"موقف سيارة واحد لعدة سيارات محتملة: الموجودة هي التي ركنت أخيرًا.","deep":"الاتحاد union بحجم أكبر أعضائه. قراءة عضو غير الذي كُتب أخيرًا غير معرَّفة تقنيًا في C++ (يسمح بها GCC)؛ و<code>memcpy</code> أو <code>std::bit_cast</code> هما الطريقتان النظيفتان لإعادة تفسير البايتات."},"extern":{"short":"تقول إن المتغيّر موجود، لكنه معرَّف في مكان آخر من البرنامج.","simple":"«المفتاح في الغرفة الأخرى»: يمكنك الحديث عنه هنا، ويجلبه الرابط لاحقًا.","deep":"تصريح بلا تعريف. يستخدمه عميل HTTPS للوصول إلى حزمة شهادات Mozilla التي يربطها البناء داخل الفلاش، عبر أسماء رموزها في الرابط."},"constexpr":{"short":"قيمة تُثبَّت عند ترجمة البرنامج، فلا يمكن أن تتغير أبدًا أثناء عمل اللوحة.","simple":"مثل رقم مطبوع على الصندوق لا مكتوب على ورقة لاصقة: محسوم قبل أن تُشغَّل اللوحة أصلًا.","deep":"تُحسب متغيّرات <code>constexpr</code> بواسطة المترجم ولا تكلّف ذاكرة RAM وقت التشغيل؛ ودالة <code>constexpr</code> مثل <code>rgb()</code> يمكن أن تعمل وقت الترجمة عندما تكون مدخلاتها ثوابت. وتسمّي المختبرات هذه <code>kSomething</code>."},"static-cast":{"short":"تحوّل قيمة إلى نوع آخر عمدًا، حيث يمكنك رؤية ذلك.","simple":"صبّ مشروب في كأس مختلفة، عمدًا وعلى مرأى من الجميع.","deep":"يفحصها المترجم وهي مجانية وقت التشغيل للأنواع العددية. الشائع هنا: <code>static_cast&lt;unsigned long&gt;</code> لمطابقة <code>%lu</code>، وإعادة <code>void *</code> إلى الكائن الذي كانته. والصيغة القصيرة <code>uint8_t(x)</code> تفعل الشيء نفسه للأنواع البسيطة."},"reinterpret-cast":{"short":"تعامل البايتات نفسها كنوع مختلف تمامًا، دون تغييرها.","simple":"قراءة صفحة أرقام كأنها حروف: الحبر نفسه، وطريقة القراءة وحدها تتغير.","deep":"لا يحدث أي تحويل؛ إنها فقط تعيد تسمية مؤشّر (مثل <code>uint8_t *</code> إلى <code>const char *</code> لمخزن بايتات نصي). يسهل إساءة استخدامها: ما زالت قواعد المحاذاة وaliasing الصارم سارية."},"const-cast":{"short":"تزيل <code>const</code> من مؤشّر ليُمرَّر إلى دالة بالأسلوب القديم.","simple":"استعارة ملصق مكتوب بالحبر لدالة لا تقبل إلا ملصقات الرصاص: تعد بأنها لن تكتب فيه فعلًا.","deep":"آمنة فقط عندما لم يكن الكائن const أصلًا، أو عندما لا تعدّله الدالة المستدعاة (كثير من واجهات C نسيت <code>const</code> ببساطة). الكتابة عبرها على بيانات const حقًّا سلوك غير معرَّف."},"template":{"short":"تكتب دالة أو صنفًا مرة واحدة لأي نوع؛ وينشئ المترجم نسخة لكل نوع مستخدم.","simple":"قالب كعك: شكل واحد، أي عجين. يقوم <code>T</code> مقام العجين إلى أن تختاره.","deep":"<code>template &lt;typename F&gt; void withChip(F &amp;&amp;fn)</code> تقبل أي شيء قابل للاستدعاء، ومنه اللامدا، دون كلفة وقت التشغيل. كل نوع جديد يعني نسخة مترجمة جديدة، فالإكثار منها يكبّر البرنامج الثابت. وتحدد الأقواس الزاوية النوع: <code>std::vector&lt;Card&gt;</code>."},"std-min-max":{"short":"تُرجع الأصغر أو الأكبر من قيمتين.","simple":"«أيهما أقل» و«أيهما أعلى»: مفيدتان لإبقاء الأعداد ضمن مدى.","deep":"يجب أن يكون المعاملان من النوع نفسه، أو تسمّيه أنت: <code>std::min&lt;uint32_t&gt;(n, 320)</code>. و<code>std::max(0, n - 9)</code> تمنع قيمة من النزول تحت الصفر."},"std-clamp":{"short":"تحصر قيمة في مدى: ما دون الحد الأدنى يعطي الحد الأدنى، وما فوق الحد الأعلى يعطي الحد الأعلى.","simple":"بوابة أطفال على الدرج: يمكنك التحرك، لكن ليس بعد البوابتين في الطرفين.","deep":"C++17، من <code>&lt;algorithm&gt;</code>. يجب أن تشترك المعاملات الثلاثة في نوع واحد، ولهذا <code>0.0f</code> و<code>1.0f</code>. وتؤدي <code>constrain()</code> في Arduino العمل نفسه."},"std-algorithms":{"short":"حلقات جاهزة من المكتبة القياسية: املأ، انسخ، رتّب، ابحث عن الأكبر...","simple":"أدوات مطبخ: يمكنك التقطيع يدويًا، لكن الأداة أسرع ولا تنزلق.","deep":"من <code>&lt;algorithm&gt;</code>، تعمل على أي مدى يُعطى ببداية ومؤشّر نهاية (أو مكرِّر iterator)، والنهاية بعد آخر عنصر. و<code>std::fill_n(buf_, n, c)</code> تلوّن شاشة كاملة؛ و<code>std::sort</code> تأخذ لامدا تقول ما معنى «يأتي أولًا»."},"std-move":{"short":"تسلّم محتويات كائن إلى آخر بدل نسخها.","simple":"الانتقال إلى بيت جديد بالصناديق كما هي، بدل شراء نسخة من كل شيء للمكان الجديد.","deep":"هي مجرد تحويل إلى مرجع rvalue (<code>T &amp;&amp;</code>)؛ أما النقل الفعلي فيقوم به مُنشئ النقل في النوع المستلِم. بعدها يكون المصدر صالحًا لكنه شبه فارغ، فلا تعتمد على قيمته. رخيصة مع <code>String</code> و<code>std::vector</code> و<code>std::function</code>."},"std-vector":{"short":"قائمة تكبر وتصغر، تحمل عناصر من نوع واحد.","simple":"ملف مجلدات قابل للتوسع: أضف أوراقًا فيفسح لها مكانًا، ويمكنك أن تقول «أعطني الورقة 3».","deep":"يخزّن العناصر في كتلة واحدة متصلة من الكومة heap ويضاعفها عند الامتلاء، مما ينقل الذاكرة (وقد يجزّئها). تملأ المختبرات المتجهات خارج المسارات الحرجة زمنيًا، مثل نسخ قائمة البطاقات للشاشة. <code>v.size()</code> و<code>v.push_back(x)</code> و<code>v[i]</code>."},"std-function":{"short":"صندوق يمكنه حمل أي دالة أو لامدا بشكل معيّن، لاستدعائها لاحقًا.","simple":"فتحة لورقة لاصقة بتعليمات: تناسبها أي ورقة، ما دامت تأخذ المدخلات نفسها.","deep":"<code>std::function&lt;void(Card &amp;)&gt;</code> تأخذ <code>Card &amp;</code> ولا تُرجع شيئًا. مرنة لكنها أثقل من القالب: استدعاؤها غير مباشر والالتقاطات الكبيرة تذهب إلى الكومة. جيدة لردود النداء المخزَّنة في صنف."},"std-atomic":{"short":"متغيّر تستطيع مهمتان قراءته وكتابته في الوقت نفسه دون أن ترى إحداهما نصف تغيير أبدًا.","simple":"مفتاح إضاءة واحد يستطيع الجميع قلبه: أيًّا كان من يلمسه فهو دائمًا مشغَّل أو مطفأ بوضوح.","deep":"<code>std::atomic&lt;bool&gt;</code> و<code>std::atomic&lt;uint32_t&gt;</code> بلا أقفال في ESP32. استخدمهما لقيمة صغيرة واحدة مثل علَم أو عدّاد؛ ولعدة قيم يجب أن تتغير معًا استخدم mutex."},"memory-order":{"short":"تحدد مدى صرامة محاذاة قراءة أو كتابة ذرّية مع الذاكرة المحيطة بها.","simple":"«Release» مثل إرسال رسالة بعد ختمها فقط؛ و«acquire» فتحها قبل قراءتها. معًا يضمنان أن يرى القارئ كل ما أعدّه الكاتب.","deep":"<code>relaxed</code> تجعل القيمة الواحدة فقط ذرّية. وتخزين <code>release</code> مقترنًا بتحميل <code>acquire</code> يجعل كل ما كُتب قبل التخزين مرئيًا بعد التحميل، عبر نواتَي ESP32. والافتراضي (<code>seq_cst</code>) هو الأصرم."},"std-mutex":{"short":"قفل يُدخل مهمة واحدة فقط في كل مرة إلى قطعة كود أو بيانات.","simple":"المفتاح الوحيد لحمّام مشترك: من يمسكه يدخل، والبقية ينتظرون عند الباب.","deep":"في Arduino-ESP32 يُبنى على mutex في FreeRTOS، فتنام المهمة المنتظِرة بدل أن تدور في مكانها. لا تقفله أبدًا داخل مقاطعة. اقفله عبر <code>std::lock_guard</code> ليُفتح دائمًا، حتى عند <code>return</code> مبكر."},"lock-guard":{"short":"يقفل mutex عند إنشائه ويفتحه تلقائيًا في نهاية الكتلة.","simple":"مفتاح يعيد نفسه: يأخذ مفتاح الحمّام عند دخولك ويعيده بنفسه عند خروجك، بأي طريقة خرجت.","deep":"RAII: يستدعي المُنشئ <code>lock()</code>، ويستدعي الهادم <code>unlock()</code> عندما يخرج المتغيّر من نطاقه. وهذا يجعل نسيان الفتح عند <code>return</code> مبكر مستحيلًا. أبقِ الكتلة قصيرة."},"decltype":{"short":"تسأل المترجم «ما نوع هذا التعبير؟» وتستخدم الجواب كنوع.","simple":"«أعطني صندوقًا مثل ذلك تمامًا.»","deep":"تُقيَّم وقت الترجمة؛ ولا يُنفَّذ التعبير أبدًا. مفيدة في القوالب ولتسمية نوع لامدا."},"static-assert":{"short":"فحص يعمل أثناء الترجمة؛ وإن فشل يتوقف البناء برسالتك.","simple":"حارس بوابة في المصنع: قطعة لا تناسب لا تغادر المبنى أبدًا.","deep":"لا تكلّف شيئًا وقت التشغيل. استخدام نموذجي: التحقق من أن struct مضغوطًا له فعلًا حجم البايتات الذي يتوقعه بروتوكول، أو أن لجدول مدخلًا واحدًا لكل قيمة enum."},"mutable":{"short":"تتيح لعضو أن يتغير حتى داخل دالة <code>const</code>، لأعمال محاسبة ليست جزءًا من قيمة الكائن.","simple":"دفتر مسوّدات مثبّت على وثيقة مختومة: الوثيقة تبقى كما هي، والملاحظات يمكن أن تتغير.","deep":"نموذجي لـ mutex أو ذاكرة مخبّئية داخل كائن دوال قراءته <code>const</code>: القفل يغيّر الـ mutex لا ما يعنيه الكائن. وعلى لامدا تتيح <code>mutable</code> أن تغيّر نسخها الملتقَطة الخاصة."},"include":{"short":"تلصق ملفًا آخر هنا، ليستطيع هذا الملف استخدام ما يصرّح به.","simple":"مثل أن تكتب «انظر بطاقة الوصفة المرفقة» في أعلى وصفة: المكوّنات المذكورة فيها صارت متاحة.","deep":"<code>&lt;Arduino.h&gt;</code> بين أقواس زاوية يبحث في مسارات المكتبات والنظام؛ و<code>\\"pins.h\\"</code> بين علامتي اقتباس يبحث بجوار هذا الملف (ومجلد <code>include/</code> للمشروع) أولًا. وهو لصق نص عادي، يتم قبل الترجمة."},"pragma-once":{"short":"تضمن أن ملف ترويسة يُلصق مرة واحدة فقط مهما كثرت الملفات التي تضمّه.","simple":"علامة «قرأتَ هذا من قبل»: في المرة الثانية تُتخطى الصفحة.","deep":"يدعمها GCC وكل المترجمات الكبرى؛ وتحلّ محل حارس التضمين الأقدم <code>#ifndef X / #define X / #endif</code>. ومن دونها يكون تعريف struct مرتين خطأ ترجمة."},"define":{"short":"تنشئ اسمًا يُستبدل بنص ما قبل ترجمة الكود.","simple":"بحث واستبدال يجريه الحاسوب قبل قراءة كودك مباشرة: كل <code>PIN_RGB</code> تصبح <code>48</code>.","deep":"الماكرو لا يعرف شيئًا عن الأنواع أو النطاق. يستخدمها <code>pins.h</code> ليتمكن علَم بناء مثل <code>-DPIN_RGB=38</code> من تجاوز طرف؛ وللثوابت العادية فضّل <code>constexpr</code>. وماكرو بأقواس مثل <code>BLE_NOTE(kind, ...)</code> يلصق معاملاته."},"conditional-compile":{"short":"تُبقي أسطر كود أو تُسقطها قبل الترجمة، بحسب تعريف اسم ما.","simple":"«إذا لم يختر أحد طرفًا بعد، فاستخدم 48.» الأسطر التي لا تنطبق تُقتطع قبل أن يراها المترجم.","deep":"<code>#ifndef PIN_RGB</code> ... <code>#endif</code> تجعل أعلام البناء في <code>platformio.ini</code> تغلب القيم الافتراضية في <code>pins.h</code>. و<code>#if</code> تختبر تعبيرًا ثابتًا؛ وكل <code>#if</code>/<code>#ifdef</code>/<code>#ifndef</code> تحتاج <code>#endif</code> مطابقة."},"serial-begin":{"short":"تفتح الخط التسلسلي إلى حاسوبك بسرعة مختارة، لتتمكن اللوحة من طباعة الرسائل.","simple":"رفع الهاتف والاتفاق على سرعة كلامكما معًا. 115200 هي السرعة التي يستمع بها المراقب التسلسلي.","deep":"السرعة بوحدة baud (بتّات في الثانية)؛ ويجب أن تطابق <code>monitor_speed</code> في <code>platformio.ini</code>. في هذه المختبرات <code>Serial</code> هو UART0، ويُوصَل عبر شريحة USB إلى تسلسلي على المنفذ <code>COM</code>، فلا شيء يحتاج إلى انتظار تعداد USB."},"serial-printf":{"short":"تطبع سطرًا في المراقب التسلسلي، وتملأ القيم برموز <code>%</code>.","simple":"خطاب نموذجي: <code>\\"%d cores\\"</code> فيه فراغ، والرقم الذي تمرّره يملؤه.","deep":"تنسّق بـ <code>vsnprintf</code> ثم تكتب إلى UART0 بسرعة 115200 baud (نحو 11.5 KB/s، فالطباعة الطويلة تبطّئ الحلقة). الرموز: <code>%d</code> int، و<code>%u</code> بلا إشارة، و<code>%lu</code> unsigned long، و<code>%.1f</code> عشري، و<code>%s</code> سلسلة C (استخدم <code>.c_str()</code> مع <code>String</code>)، و<code>%02X</code> ست عشري برقمين. وأضف <code>\\\\n</code> بنفسك."},"serial-print":{"short":"تطبع نصًّا أو رقمًا في المراقب التسلسلي؛ و<code>println</code> تبدأ سطرًا جديدًا أيضًا.","simple":"قول شيء بصوت عالٍ لحاسوبك. و<code>println</code> مثل ضغط Enter بعد ذلك.","deep":"تقبل النص والأعداد و<code>String</code>؛ و<code>Serial.print(x, HEX)</code> تطبع بالست عشري. تكتب في مخزن إرسال ولا تنتظر إلا عندما يمتلئ."},"serial-read":{"short":"<code>available()</code> تقول كم حرفًا مكتوبًا ينتظر؛ و<code>read()</code> تأخذ التالي.","simple":"فحص صندوق الرسائل: <code>available()</code> تخبرك كم رسالة فيه، و<code>read()</code> تُخرج واحدة.","deep":"كلتاهما تعودان فورًا؛ و<code>read()</code> تعطي -1 عندما لا شيء ينتظر. تجمع المختبرات الحروف في مخزن مؤقت حتى سطر جديد ثم تنفّذ الأمر، فلا تحجب الكتابة الشاشة أبدًا. و<code>flush()</code> تنتظر حتى يُرسَل كل ما طُبع."},"pin-mode":{"short":"تهيّئ طرف GPIO كمدخل أو مخرج قبل استخدامه.","simple":"تقرير ما إذا كان الباب للدخول (قراءة زر) أو للخروج (إضاءة LED).","deep":"تضبط مصفوفة GPIO لذلك الطرف. و<code>INPUT_PULLUP</code> تشغّل أيضًا مقاومة داخلية ضعيفة إلى 3.3 V، فلا يحتاج زر موصول إلى GND إلى قطع إضافية. تجنّب أطراف الإقلاع (strapping) والفلاش وPSRAM المذكورة في أعلى <code>pins.h</code>."},"pin-modes":{"short":"الطرق التي يمكن بها ضبط طرف: الاستماع، أو القيادة، أو الاستماع بمقاومة مدمجة.","simple":"<code>OUTPUT</code> صنبور تفتحه وتغلقه. و<code>INPUT</code> مقياس تقرؤه. و<code>INPUT_PULLUP</code> مقياس يستقر عند «مرتفع» حتى يسحبه شيء إلى الأسفل.","deep":"المدخل العائم <code>INPUT</code> يلتقط الضجيج؛ و<code>INPUT_PULLUP</code>/<code>INPUT_PULLDOWN</code> تفعّلان المقاومات الداخلية الضعيفة في ESP32 (عشرات الكيلو أوم). ولهذا يُقرأ الزر المضغوط <code>LOW</code> في هذه المختبرات."},"digital-write":{"short":"تشغّل طرف مخرج (3.3 V) أو تطفئه (0 V).","simple":"قلب مفتاح إضاءة: <code>HIGH</code> مشغَّل و<code>LOW</code> مطفأ.","deep":"أطراف ESP32-S3 تعمل بـ 3.3 V، وليس 5 V أبدًا. يستطيع كل طرف أن يمدّ أو يمتص نحو 20 mA افتراضيًا (قابلة للضبط بـ <code>gpio_set_drive_capability</code>)، فيحتاج LED دائمًا إلى مقاومة على التسلسل."},"digital-read":{"short":"تقرأ هل طرف المدخل مرتفع (قرب 3.3 V) أو منخفض (قرب 0 V).","simple":"سؤال زر جرس الباب: هل أنت مضغوط الآن؟","deep":"تُرجع <code>HIGH</code> (1) أو <code>LOW</code> (0). ومع <code>INPUT_PULLUP</code> يُقرأ الزر المضغوط <code>LOW</code>، ولذلك تعني <code>== LOW</code> «مضغوط». تتذبذب الملامسات الميكانيكية بضعة ms، ويرشّحها <code>Button</code>."},"high-low":{"short":"المستويان في الطرف الرقمي: <code>HIGH</code> هو 3.3 V و<code>LOW</code> هو 0 V.","simple":"تشغيل وإيقاف، بلغة الجهد.","deep":"هما ببساطة 1 و0. في ESP32 يقرأ المدخل <code>HIGH</code> فوق نحو ثلاثة أرباع 3.3 V و<code>LOW</code> تحت ربعها؛ وما بينهما غير مضمون."},"analog-read":{"short":"تقيس الجهد على طرف كعدد من 0 إلى 4095.","simple":"قراءة معتّمة بدل مفتاح تشغيل/إيقاف: إلى أي مدى ارتفع الجهد على مقياس من 0 إلى 4095؟","deep":"المحوّل ADC في ESP32-S3 بدقة 12 بتًّا. استخدم أطراف ADC1 (GPIO 1-10): ADC2 مشترك مع Wi-Fi. والاستدعاء الواحد عيّنة بطيئة واحدة، ولهذا تستخدم مختبرات الصوت الوضع المتواصل لـ ADC مع DMA بدلًا منه."},"millis":{"short":"كم مللي ثانية مرّت منذ بدء تشغيل اللوحة.","simple":"ساعة إيقاف تبدأ عند التشغيل ولا تتوقف أبدًا. قارنها بقراءة سابقة لتعرف كم مضى.","deep":"تُرجع <code>unsigned long</code> بحجم 32 بتًّا مشتقًّا من <code>esp_timer</code> ذي 64 بتًّا. تلتف إلى 0 بعد نحو 49.7 يومًا، ويبقى <code>millis() - last >= interval</code> صحيحًا عبر الالتفاف بفضل الحساب بلا إشارة. وهكذا تفعل الحلقات أشياء «كل N ms» دون <code>delay()</code>."},"micros":{"short":"كم ميكروثانية (جزء من مليون من الثانية) مرّت منذ بدء تشغيل اللوحة.","simple":"ساعة الإيقاف نفسها كما في <code>millis()</code>، تُقرأ بدقة أكبر بألف مرة.","deep":"32 بتًّا، فتلتف بعد نحو 71.6 دقيقة؛ لا بأس بها لتوقيت الأشياء القصيرة، واستخدم <code>esp_timer_get_time()</code> لساعة 64 بتًّا لا تلتف عمليًا أبدًا."},"delay":{"short":"توقف الكود الحالي مدة من المللي ثانية.","simple":"أخذ قيلولة: لا يحدث شيء آخر في <code>loop()</code> حتى تستيقظ.","deep":"في ESP32 تستدعي <code>vTaskDelay</code>، فتتحرر وحدة المعالجة لمهام أخرى (Wi-Fi وBLE والمُعيِّن) بينما تنام هذه. نبضة FreeRTOS هنا 1 ms. ومع ذلك تجمّد التأخيرات الطويلة الأزرار والشاشة، لذا تعتمد المختبرات غالبًا على فحوص <code>millis()</code>."},"delay-microseconds":{"short":"تنتظر عددًا صغيرًا جدًا من الميكروثواني، لعتاد يحتاج توقفات قصيرة جدًا.","simple":"حبس النفَس لطرفة عين: أقصر من أن تُغفي، فتنتظر في مكانك.","deep":"انتظار مشغول: تدور وحدة المعالجة ولا تعمل المهام الأخرى على هذه النواة. لا بأس بها لبضع مئات من الميكروثواني (لتستقر مقاومة السحب)، وليست للانتظار الطويل أبدًا."},"ledc-attach":{"short":"تحوّل طرفًا إلى مخرج PWM بتردد ودقة مختارين، لتعتيم LED أو الإضاءة الخلفية.","simple":"إعداد مفتاح إضاءة سريع جدًا يُشغَّل ويُطفأ آلاف المرات في الثانية، فترى العين «نصف سطوع».","deep":"واجهة Arduino-ESP32 3.x على عتاد LEDC: تُرجع <code>ledcAttach(pin, freq, bits)</code> القيمة <code>false</code> إذا لم تناسب أي قناة أو تردد. وتعطي 5 kHz بدقة 8 بتّات قيم دورة تشغيل 0-255 بلا وميض مرئي."},"ledc-write":{"short":"تحدد كم من كل دورة PWM يبقى الطرف مشغَّلًا: 0 مطفأ، والقيمة العليا مشغَّل بالكامل.","simple":"إدارة قرص التعتيم على ذلك المفتاح السريع.","deep":"في Arduino-ESP32 3.x تأخذ الطرف (وكانت 2.x تأخذ قناة). مدى دورة التشغيل من 0 إلى 2^bits - 1 (0-255 لـ 8 بتّات) من <code>ledcAttach</code>؛ ويُبقي عتاد LEDC الموجة تعمل دون عمل من وحدة المعالجة."},"rgb-led-write":{"short":"تضبط لون LED الـ RGB المدمج في اللوحة من قيم الأحمر والأخضر والأزرق (0-255 لكل منها).","simple":"خلط الطلاء: قليل من الأحمر، وكثير من الأخضر، ولا أزرق. يعرض LED الخليط.","deep":"LED المدمج هو WS2812 يأخذ اللون كقطار نبضات موقَّتة بدقة؛ ويولّده Arduino-ESP32 بعتاد RMT. وهو ساطع جدًا، لذا تخفّض المختبرات القيم. وكانت تسمى <code>neopixelWrite</code> في النوى الأقدم."},"attach-interrupt":{"short":"تشغّل دالة في اللحظة التي يتغير فيها طرف، حتى والكود الباقي مشغول.","simple":"جرس باب بدل النظر من النافذة: تُقاطَع اللوحة لحظة يضغط أحدهم.","deep":"<code>CHANGE</code> أو <code>RISING</code> أو <code>FALLING</code> تختار أي الحواف تُطلق. وتمرّر <code>attachInterruptArg</code> أيضًا <code>void *</code> (هنا <code>this</code>) ليجد معالج static كائنه. يجب أن تكون المعالجات قصيرة ومعلَّمة <code>IRAM_ATTR</code>، وألا تلمس إلا بيانات <code>volatile</code> أو ذرّية."},"digital-pin-to-interrupt":{"short":"تحوّل رقم طرف إلى رقم المقاطعة الذي تتوقعه <code>attachInterrupt</code>.","simple":"البحث عن أي سلك جرس يخص أي باب.","deep":"في ESP32 يمكن لكل GPIO أن يقاطع ورقمه هو الطرف نفسه، لكن كتابتها تُبقي الكود قابلًا للنقل إلى لوحات يختلف فيها ذلك."},"random":{"short":"تختار عددًا صحيحًا عشوائيًا: <code>random(40, 200)</code> تعطي من 40 حتى 199.","simple":"رمي نرد تختار أنت أوجهه. الرقم الأعلى لا يخرج أبدًا.","deep":"<code>random(max)</code> تعطي من 0 إلى max-1، و<code>random(min, max)</code> من min إلى max-1. و<code>randomSeed(esp_random())</code> تبدأ المتتالية من رقم عشوائي عتادي، فيبدو كل إقلاع مختلفًا."},"constrain":{"short":"تُبقي قيمة بين أدنى قيمة وأعلى قيمة مسموحتين.","simple":"حواجز في ممر البولينغ: تتدحرج الكرة في أي مكان بينها، ولا تتجاوزها أبدًا.","deep":"نسخة Arduino من <code>std::clamp</code>: <code>constrain(x, lo, hi)</code>. يجب أن تبقى نغمات MIDI وشدّتها بين 0 و127، ولذلك يحصرها مختبر BLE MIDI."},"min-max":{"short":"اختصار Arduino للأصغر أو الأكبر من قيمتين.","simple":"«أيهما أصغر» أو «أيهما أكبر». <code>max(2, s / 6)</code> تعني «على الأقل 2».","deep":"أعطِ المعاملين النوع نفسه لتجنب المفاجآت. وفي أماكن أخرى تكتب المختبرات <code>std::min</code>/<code>std::max</code> وهما تقبلان نوعًا صريحًا أيضًا: <code>std::min&lt;uint32_t&gt;(n, 320)</code>."},"string-c-str":{"short":"تعطي نص <code>String</code> كسلسلة C عادية، للدوال التي تريد <code>const char *</code>.","simple":"إخراج الحروف من دفترها المطّاطي ووضعها على الطاولة، لمن لا يقرأ إلا القطع.","deep":"المؤشّر صالح فقط ما دام <code>String</code> حيًّا ولم يتغير؛ لا تحتفظ به أبدًا من كائن مؤقت مثل <code>a.toString().c_str()</code> بعد ذلك السطر. مطلوبة لـ <code>%s</code> في printf."},"string-is-empty":{"short":"اسأل <code>String</code> هل هو بلا حروف، أو كم حرفًا فيه.","simple":"هل صفحة الدفتر فارغة؟ كم حرفًا عليها؟","deep":"تعدّ <code>length()</code> المحارف (بالبايت، فيُحسب الإيموجي عدة بايتات) ولا تشمل <code>'\\\\0'</code> المخفي. و<code>isEmpty()</code> مثل <code>length() == 0</code> وأوضح قراءةً."},"string-substring":{"short":"<code>indexOf</code> تجد أين يظهر نص ما؛ و<code>substring</code> تقتطع قطعة.","simple":"إيجاد كلمة في جملة بإصبعك، ثم قصّ الجزء الذي تحتاجه بالمقص.","deep":"المواضع تُعدّ من 0. و<code>substring(from)</code> تذهب إلى النهاية، و<code>substring(from, to)</code> تتوقف قبل <code>to</code> مباشرة. و<code>indexOf</code> تُرجع -1 عندما لا تجد شيئًا. وكل <code>substring</code> تُنشئ <code>String</code> جديدًا في الكومة heap."},"string-starts-with":{"short":"تفحص هل يبدأ <code>String</code> (أو ينتهي) بنص ما.","simple":"«هل يبدأ هذا الأمر بـ 'vol '؟» نعم أو لا بسرعة.","deep":"حساسة لحالة الأحرف، ولهذا تُحوَّل الأوامر إلى أحرف صغيرة أولًا (<code>lower.startsWith(...)</code>). وهكذا يتعرف محلل أوامر المنفذ التسلسلي في كل مختبر على كلماته."},"string-trim":{"short":"تنظيف النص في مكانه: أزل المسافات من الطرفين، أو غيّر حالة الأحرف، أو استبدل قطعة نص بأخرى.","simple":"تقويم ورقة قبل قراءتها: لا مسافات زائدة، وكلها بأحرف صغيرة، فيعني «Help » و«help» الشيء نفسه.","deep":"تغيّر هذه الدوال <code>String</code> نفسه ولا تُرجع شيئًا، فاستدعها على نسخة تملكها: <code>String lower = line; lower.toLowerCase();</code>. و<code>trim</code> تزيل أيضًا <code>\\\\r</code> الذي ترسله بعض الطرفيات."},"string-to-int":{"short":"تحوّل نصًّا مثل <code>\\"42\\"</code> إلى العدد 42.","simple":"قراءة الأرقام على ورقة وكتابتها في آلة حاسبة.","deep":"تُرجع <code>long</code> (أو <code>float</code>). والنص الذي لا يبدأ بعدد يعطي 0، فيبدو <code>0</code> المكتوب والكلام العشوائي سواء؛ افحص النص عندما يهم ذلك."},"spi-begin":{"short":"تبدأ ناقل SPI على الأطراف التي تختارها، لتتحدث اللوحة بسرعة مع الشاشة أو قارئ RFID.","simple":"مدّ خط هاتف خاص بأسلاك منفصلة للكلام والاستماع والإيقاع الذي يضبط الطرفان وقتهما عليه.","deep":"<code>SPI.begin(sck, miso, mosi, ss)</code>؛ و-1 تتخطى طرفًا (الشاشة بلا MISO). و<code>SPI</code> هو SPI2 (FSPI) في S3؛ ويبني مسار RFID <code>SPIClass</code> ثانيًا على SPI3 فلا يتشاركان الأسلاك أو التوقيت أبدًا."},"log-macros":{"short":"تطبع سطر سجلّ موسومًا: <code>i</code> معلومة، و<code>w</code> تحذير، و<code>e</code> خطأ، و<code>d</code> تنقيح.","simple":"ملاحظات في سجلّ سفينة، لكل منها ختم يبيّن مدى خطورتها.","deep":"ماكروهات Arduino-ESP32 بقوالب على نمط printf. يُسبق كل سطر بالمستوى والملف والسطر والدالة، وتُزال الأسطر فوق <code>CORE_DEBUG_LEVEL</code> (القيمة 3 = معلومة في <code>platformio.ini</code>) وقت الترجمة، فلا تكلّف <code>log_d</code> شيئًا هنا. ويذهب الخرج إلى المنفذ التسلسلي نفسه مثل <code>Serial</code>."},"esp-info":{"short":"اسأل الرقاقة عن نفسها: الطراز، والنوى، والسرعة، وحجم الفلاش وPSRAM، وعنوان MAC.","simple":"اللوحة تقرأ بطاقة هويتها بصوت عالٍ.","deep":"يتوقع الدرس 01 رقاقة <i>ESP32-S3</i>، بنواتين على 240 MHz، وفلاش 16 MB (الطراز N16) ونحو 8 MB من PSRAM (الطراز R8). و<code>getEfuseMac()</code> تُرجع عنوان MAC من المصنع من eFuse على شكل <code>uint64_t</code>، البايت الأدنى أولًا."},"free-heap":{"short":"كم من الذاكرة ما زال حرًّا لحجوزات جديدة.","simple":"فحص المساحة المتبقية في الخزانة قبل شراء المزيد.","deep":"<code>ESP.getFreeHeap()</code> تعدّ ذاكرة RAM الداخلية؛ و<code>heap_caps_get_free_size(MALLOC_CAP_SPIRAM)</code> تعدّ PSRAM. الحرّ ليس هو المستخدَم: تخبرك <code>heap_caps_get_largest_free_block</code> بأكبر قطعة منفردة، وهذا ما يحتاجه مخزن الإطار."},"esp-restart":{"short":"تعيد تشغيل الرقاقة من الصفر، كأنك ضغطت زر إعادة الضبط.","simple":"إطفاؤها وتشغيلها من جديد، من داخل البرنامج.","deep":"إعادة ضبط برمجية: تُمسح RAM، وتبقى NVS (Preferences)، وتبلّغ <code>esp_reset_reason()</code> عن <code>ESP_RST_SW</code> في المرة التالية. تُستخدم بعد تغيير إعداد محفوظ لا يسري إلا عند البدء."},"esp-reset-reason":{"short":"تخبرك لماذا بدأت اللوحة آخر مرة: تشغيل الطاقة، أو زر إعادة الضبط، أو انهيار، أو هبوط الجهد...","simple":"تستيقظ وتسأل «هل نمتُ للتو، أم سقطتُ؟»","deep":"تُرجع <code>esp_reset_reason_t</code> مثل <code>ESP_RST_POWERON</code> أو <code>ESP_RST_SW</code> أو <code>ESP_RST_PANIC</code> أو <code>ESP_RST_TASK_WDT</code> أو <code>ESP_RST_BROWNOUT</code> (هبط جهد التغذية). وطباعتها عند الإقلاع تجعل الانهيارات مرئية."},"esp-timer-get-time":{"short":"الميكروثواني منذ الإقلاع، من ساعة 64 بتًّا لا تنفد أبدًا.","simple":"ساعة إيقاف دقيقة جدًا: جيدة لقياس كم استغرق رسم إطار شاشة واحد.","deep":"تُرجع <code>int64_t</code> من مؤقت ESP-IDF عالي الدقة؛ ويمكن استدعاؤها بأمان من مقاطعة. و<code>millis()</code> و<code>micros()</code> مبنيتان عليها. ويحتفظ معالج الزر بالبتّات الـ 32 الدنيا فقط ليكون كل قراءة خطوة واحدة."},"esp-timer":{"short":"تُعدّ رد نداء ينفّذه ESP-IDF بعد تأخير أو بنبض منتظم، بتوقيت بالميكروثانية.","simple":"مؤقت مطبخ يرنّ كل 125 ms، مهما كان الكود الباقي يفعل.","deep":"تعمل ردود النداء في مهمة <code>esp_timer</code> العالية الأولوية، لا في <code>loop()</code>، فأبقِها قصيرة وشارك البيانات بأمان. والفترات بالميكروثانية."},"esp-random":{"short":"عدد عشوائي من 32 بتًّا من مولّد الأعداد العشوائية العتادي في الرقاقة.","simple":"نرد يرميه الفيزياء داخل الرقاقة لا معادلة.","deep":"عشوائي حقًّا ما دام Wi-Fi أو Bluetooth يعمل (ضجيج الراديو يغذّيه)؛ وقبل ذلك عامله على أنه شبه عشوائي فقط. و<code>esp_fill_random(buf, n)</code> تملأ مخزنًا مؤقتًا، كما يفعل مختبر الخزنة لمفتاحه السري."},"heap-caps-malloc":{"short":"تطلب كتلة ذاكرة من نوع مختار من RAM: الداخلية السريعة أو PSRAM الخارجية الكبيرة.","simple":"الاختيار بين الدرج الصغير على مكتبك (سريع الوصول) والمخزن الكبير في آخر الممر (واسع لكنه أبطأ).","deep":"في S3 نحو 512 KB من SRAM الداخلية، وهنا 8 MB من PSRAM الثمانية (octal). تختار <code>MALLOC_CAP_INTERNAL</code> أو <code>MALLOC_CAP_SPIRAM</code> المجمّع؛ والنتيجة <code>nullptr</code> إذا لم توجد كتلة كبيرة بما يكفي. حرّرها بـ <code>heap_caps_free</code>."},"gpio-drive":{"short":"تختار مدى قوة دفع طرف المخرج للتيار، من ضعيفة إلى قوية.","simple":"ضبط مدى قوة دفع الصنبور للماء: خيط رفيع أو ضغط كامل.","deep":"استدعاء من ESP-IDF (يحتاج <code>gpio_num_t</code>، ولذلك التحويل). المستويات 0-3 تقارب 5 و10 و20 (الافتراضي) و40 mA. والقيادة الأضعف تجعل الحواف أنعم وتُبقي LED أخفت."},"esp-err":{"short":"دوال ESP-IDF تجيب برمز نتيجة؛ و<code>ESP_OK</code> (0) يعني أنها نجحت.","simple":"إيصال: «حسنًا»، أو سبب عدم النجاح.","deep":"أي قيمة أخرى خطأ مثل <code>ESP_ERR_NO_MEM</code> أو <code>ESP_ERR_TIMEOUT</code>؛ و<code>esp_err_to_name()</code> تحوّلها إلى نص للسجل. وتفحص المختبرات <code>!= ESP_OK</code> وتخرج بدل أن تنهار."},"preferences":{"short":"تحفظ إعدادات صغيرة في فلاش الرقاقة لتبقى بعد انقطاع الطاقة وإعادة رفع البرنامج.","simple":"دفتر ملصق داخل اللوحة: اكتب «اسم Wi-Fi = home» فيبقى هناك غدًا.","deep":"غلاف Arduino حول NVS في ESP-IDF، مخزن مفتاح-قيمة في قسم فلاش خاص به. <code>begin(\\"ns\\", readOnly)</code> تفتح فضاء أسماء؛ وفضاءات الأسماء والمفاتيح لا تتجاوز 15 حرفًا. غير مشفّر افتراضيًا؛ استدعِ <code>end()</code> عند الانتهاء."},"preferences-put-get":{"short":"اكتب قيمة تحت مفتاح، أو اقرأها مع قيمة بديلة إذا لم تُحفظ قط.","simple":"برطمانات معنونة على رف: ضع شيئًا في البرطمان المسمّى «vol»، ثم أخرجه لاحقًا.","deep":"النوع في الاسم (<code>UChar</code> = <code>uint8_t</code> و<code>UInt</code> = <code>uint32_t</code>). و<code>getX(key, fallback)</code> تُرجع القيمة البديلة عندما يغيب المفتاح. وتكلّف الكتابة تآكلًا في الفلاش، لذا لا تحفظ المختبرات إلا عند التغيير."},"x-task-create":{"short":"تبدأ مهمة جديدة: دالة تعمل بجانب <code>loop()</code>، على نواة تختارها.","simple":"توظيف طاهٍ ثانٍ. له وصفته الخاصة ويعمل في الوقت نفسه معك، على موقده.","deep":"المعاملات: الدالة، والاسم، وحجم المكدّس، ومعامل <code>void *</code> (غالبًا <code>this</code>)، والأولوية، ومقبض اختياري، والنواة. في ESP-IDF حجم المكدّس بـ<b>البايتات</b>. وتعمل <code>loop()</code> على النواة 1؛ وتثبّت المختبرات قارئاتها ومُعيِّناتها على النواة 0. وتُرجع <code>pdPASS</code> عند النجاح."},"v-task-delay":{"short":"تُنيم هذه المهمة عددًا من النبضات، لتحصل المهام الأخرى على وحدة المعالجة.","simple":"الطاهي الثاني يبتعد عن الموقد لحظة ليستخدمه غيره.","deep":"النبضة 1 ms في Arduino-ESP32، لكن اكتب <code>pdMS_TO_TICKS(ms)</code> ليتضح المعنى. يجب أن تُحجب حلقة المهمة اللانهائية أو تتأخر في مكان ما، وإلا جاعت المهام الأقل أولوية واشتكى الحارس watchdog."},"pd-ms-to-ticks":{"short":"تحوّل المللي ثانية إلى نبضات FreeRTOS، وهي الوحدة التي يستخدمها كل انتظار في FreeRTOS.","simple":"ترجمة الدقائق إلى وحدات ساعة المطبخ نفسها.","deep":"ماكرو: <code>ms * configTICK_RATE_HZ / 1000</code>. مع نبضة 1000 Hz هنا هي واحد لواحد، لكن الكود يبقى صحيحًا إذا تغير معدل النبض. والانتظارات الأقصر من نبضة تُقرَّب إلى 0."},"port-max-delay":{"short":"«انتظر إلى الأبد»: مرّرها كمهلة لتحجب حتى يصل شيء.","simple":"الجلوس عند صندوق البريد حتى يصل البريد، مهما استغرق ذلك.","deep":"أكبر عدد نبضات، ويعدّه FreeRTOS بلا مهلة. جيد لمهمة عاملة ليس لديها ما تفعله غير ذلك؛ ولا تستخدمه أبدًا في <code>loop()</code> أو مقاطعة."},"pd-true":{"short":"إجابات نعم/لا الخاصة بـ FreeRTOS: <code>pdTRUE</code>/<code>pdPASS</code> تعنيان أنها نجحت.","simple":"الإيصال الذي يعيده FreeRTOS بعد طلب طابور أو مهمة.","deep":"أعداد صحيحة عادية (<code>BaseType_t</code>)، 1 للصحيح/النجاح و0 للخطأ/الفشل. قارن معها صراحةً: <code>xQueueSend(...) == pdTRUE</code>."},"x-queue-create":{"short":"تنشئ طابورًا: صندوق بريد آمنًا لتمرير العناصر من مهمة إلى أخرى.","simple":"صندوق بريد بعدد ثابت من الخانات: مهمة تُسقط فيه رسائل وأخرى تُخرجها، ولا تتصادمان أبدًا.","deep":"تُرجع <code>xQueueCreate(length, itemSize)</code> قيمة <code>QueueHandle_t</code>، أو null إذا نفدت الذاكرة. تُ<b>نسخ</b> العناصر إلى الداخل والخارج، فأرسل بنى صغيرة لا مؤشّرات إلى أشياء قد تختفي."},"x-queue-send":{"short":"تضع نسخة من عنصر في طابور، وتنتظر مهلة إذا كان ممتلئًا.","simple":"إسقاط رسالة في صندوق البريد. إذا امتلأ الصندوق يمكنك الانتظار لحظة أو الانصراف.","deep":"مهلة 0 لا تحجب أبدًا وتُرجع <code>errQUEUE_FULL</code> عندما لا يوجد مكان: مناسبة لـ <code>loop()</code> ومعالجات الويب التي يجب ألا تتوقف. ومن مقاطعة استخدم نسخة <code>FromISR</code>."},"x-queue-receive":{"short":"تأخذ العنصر التالي من طابور، وتنتظر مهلة إذا كان فارغًا.","simple":"فتح صندوق البريد: خذ أقدم رسالة، أو انتظر قليلًا حتى تصل واحدة.","deep":"تخرج العناصر بالترتيب، منسوخة في متغيّرك. وتحجب مهمة عاملة هنا عادةً بمهلة (أو <code>portMAX_DELAY</code>)، فلا تستهلك وحدة المعالجة حتى يصل عمل."},"semaphore":{"short":"إشارة تنتظرها مهمة وتعطيها أخرى (أو مقاطعة).","simple":"عصا في سباق تتابع: ينتظر العدّاء حتى تُسلَّم العصا، ثم ينطلق.","deep":"يرقد مشغّل MFRC522 في <code>xSemaphoreTake(done_, timeout)</code> حتى تستدعي مقاطعة IRQ للقارئ <code>xSemaphoreGiveFromISR</code>، فلا حاجة إلى استطلاع SPI. ويضيف semaphore من نوع mutex وراثة الأولوية للقفل."},"task-handle":{"short":"المقبض يسمّي مهمة قيد التشغيل؛ و<code>vTaskDelete</code> تُنهي واحدة.","simple":"شارة اسم الطاهي الثاني، والورقة التي تعيده إلى بيته.","deep":"<code>vTaskDelete(nullptr)</code> تُنهي المهمة المستدعِية؛ ويجب ألا تعود دالة المهمة بـ return فحسب. و<code>uxTaskGetStackHighWaterMark</code> تُظهر مدى اقتراب مهمة من فيضان مكدّسها."},"critical-section":{"short":"تقفل بضعة أسطر فلا تستطيع أي مهمة أو نواة أو مقاطعة أخرى لمس البيانات نفسها في الأثناء.","simple":"إبقاء الباب مغلقًا بقدمك لحظة وأنت تبدّل شيئين على الرف.","deep":"تأخذ قفل دوران <code>portMUX_TYPE</code> وتعطّل المقاطعات على هذه النواة، فتعمل عبر نواتَي ESP32 ومع المقاطعات. أبقِ المقطع بضع نسخات: بلا طباعة ولا انتظار ولا حجز ذاكرة."},"adafruit-st7789":{"short":"المشغّل لشاشة ملونة 1.9 بوصة بدقة 320×170 تُستخدم من الدرس 03.","simple":"المترجم الفوري بين اللوحة والشاشة: تقول «ارسم هذا»، فيتكلم بلغة الشاشة عبر SPI.","deep":"مشغّل ST7789 من Adafruit. <code>init(170, 320)</code> تضبط حجم اللوحة، و<code>setRotation(1)</code> تجعلها أفقية، و<code>setSPISpeed</code> ترفع الساعة إلى 40 MHz. والبكسلات RGB565."},"adafruit-gfx":{"short":"مكتبة الرسم وراء كل استدعاء شاشة: خطوط ودوائر ومستطيلات ونص.","simple":"صندوق من القوالب والأقلام. أي شاشة تستطيع تلوين بكسل واحد تحصل على كل الأشكال الأخرى مجانًا.","deep":"صنف أساسي مجرّد: يكفي أن ينفّذ الصنف الفرعي <code>drawPixel</code>، وكل شيء آخر مبني عليها (و<code>FrameBuffer</code> عندنا يتجاوز أيضًا استدعاءات الخط والتعبئة للسرعة). الإحداثيات <code>int16_t</code>، من الزاوية العليا اليسرى."},"gfx-canvas16":{"short":"صورة خارج الشاشة في الذاكرة ترسم عليها، ثم ترسلها إلى الشاشة دفعة واحدة.","simple":"الرسم على ورقة أولًا ثم رفع الصفحة المنتهية أمام النافذة، فلا يرى أحد نصف رسمة.","deep":"لوحة Adafruit GFX ذات 16 بتًّا: <code>uint16_t</code> لكل بكسل، 320×170×2 = نحو 106 KB. تحجز بـ <code>malloc</code> العادية التي تقع هنا في PSRAM؛ أما <code>FrameBuffer</code> عندنا فيفضّل RAM الداخلية."},"frame-buffer":{"short":"الصورة خارج الشاشة في هذا المشروع: ارسم فيها باستدعاءات GFX العادية، ثم ادفعها إلى الشاشة.","simple":"لوح رسمنا الخاص، محفوظ في أسرع درج فيه مكان.","deep":"معرَّف في <code>kit/lib/bench/src/frame_buffer.h</code>. تجرّب <code>begin()</code> أولًا RAM الداخلية السريعة ثم تلجأ إلى PSRAM، وتقول <code>internal()</code> أيّهما حصلت عليه. وتتجاوز <code>drawPixel</code> و<code>fillScreen</code> واستدعاءات الخط والمستطيل بكتابات مباشرة في <code>pixels()</code>."},"display":{"short":"مساعد الشاشة في هذا المشروع: ST7789 وإضاءتها الخلفية ومخزن الإطار، تُعدّ بالطريقة نفسها في كل مختبر.","simple":"الشاشة ولوح رسمها معبّآن معًا: ارسم على <code>fb()</code>، ثم تعرضه <code>push()</code>.","deep":"معرَّف في <code>kit/lib/bench/src/display.h</code>. تبدأ <code>begin()</code> PWM على الإضاءة الخلفية وSPI على 40 MHz واللوحة في الوضع الأفقي؛ وترسل <code>push()</code> الصورة كلها بـ <code>drawRGBBitmap</code> واحدة."},"button":{"short":"مساعد الزر في هذا المشروع: يحوّل الضغطات الخام إلى نقرات ونقرات مزدوجة وضغطات طويلة نظيفة.","simple":"بوّاب للزر: يتجاهل ارتجاف الملامسات المعدنية ويخبرك بما قصده الشخص فعلًا.","deep":"معرَّف في <code>kit/lib/bench/src/button.h</code>. مقاطعة <code>IRAM_ATTR</code> تعدّ كل حافة؛ و<code>poll()</code> تقبل مستوى جديدًا بعد 25 ms من الهدوء وتبلّغ عن <code>Event::Click</code> أو <code>DoubleClick</code> (خلال 280 ms) أو <code>LongPress</code> (600 ms)."},"lab-shell":{"short":"الغلاف المشترك الذي تُبنى عليه مختبرات كل مسار: الشاشة والزر وLED وأوامر المنفذ التسلسلي والخطّافات.","simple":"طاولة عمل جاهزة. كل مختبر يجلب أدواته فقط (العروض والأوامر) ويوصلها.","deep":"المختبر هو <code>...Spec</code>: عروضه (دوال رسم مع إجراء النقر المزدوج) وأوامره التسلسلية وخطّافات مثل <code>setup</code> و<code>tick</code> و<code>gesture</code>. وتطبع <code>lab.warn</code> و<code>lab.note</code> رسائل بنمط printf إلى السجل وإلى الشاشة. و<code>src/&lt;lab&gt;/main.cpp</code> في كل مختبر هو في معظمه تلك القائمة، فيُظهر <code>help</code> بالضبط ما يعلّمه الدرس."},"mfrc522":{"short":"مشغّل هذا المشروع الخاص لقارئ البطاقات RC522، مكتوب مسجّلًا مسجّلًا بلا مكتبة.","simple":"التحدث إلى شريحة القارئ مباشرة، بايتًا بايتًا، لترى كل كلمة في المحادثة.","deep":"معرَّف في <code>kit/lib/rfid-kit/src/mfrc522.h</code>: تأطير SPI والمسجّلات وFIFO ومؤقت الشريحة، مع الاستطلاع أو النوم على سلك IRQ الخاص بها. ويبني <code>iso14443a.h</code> و<code>mifare_classic.h</code> بروتوكول البطاقة فوقه."},"rgb565":{"short":"تحوّل الأحمر والأخضر والأزرق (أو درجة لون على عجلة الألوان) إلى لون شاشة واحد من 16 بتًّا.","simple":"خلط الطلاء، ثم كتابة الخليط برمز واحد تفهمه الشاشة.","deep":"يحتفظ RGB565 بـ 5 بتّات للأحمر و6 للأخضر و5 للأزرق: <code>((r &amp; 0xF8) &lt;&lt; 8) | ((g &amp; 0xFC) &lt;&lt; 3) | (b &gt;&gt; 3)</code>. و<code>rgb()</code> عندنا <code>constexpr</code>، فألوان اللوحة لا تكلّف شيئًا وقت التشغيل."},"gfx-fill-screen":{"short":"تطلي الشاشة كلها (أو اللوحة) بلون واحد.","simple":"طبقة طلاء جديدة فوق كل شيء، وغالبًا هي الخطوة الأولى لرسم إطار جديد.","deep":"في <code>FrameBuffer</code> عندنا هي <code>std::fill_n</code> واحدة على 54 400 بكسل؛ وعلى اللوحة نفسها تبثّ هذا العدد من البكسلات عبر SPI."},"gfx-draw-pixel":{"short":"تلوّن نقطة واحدة فقط عند x وy.","simple":"نقطة واحدة من قلم تحديد.","deep":"الدالة الوحيدة التي يجب أن توفّرها كل سطح Adafruit GFX؛ وكل الأشكال الأخرى يمكن بناؤها منها. ودالتنا تفحص الحدود وتكتب <code>buf_[y * _width + x]</code>."},"gfx-rect":{"short":"ترسم مستطيلًا من زاويته العليا اليسرى وعرضه وارتفاعه: ممتلئًا أو بحدود فقط أو بزوايا مستديرة.","simple":"ختم شكل صندوق على الصورة.","deep":"المعاملات: <code>(x, y, w, h, colour)</code>، مع نصف قطر للزاوية في النسخ المستديرة. و<code>fill</code> تطلي الداخل، و<code>draw</code> الحدود فقط. الأشرطة واللوحات والأزرار في كل شاشة مختبر مصنوعة منها."},"gfx-circle":{"short":"ترسم أشكالًا مستديرة ومثلثات: دوائر من مركز ونصف قطر، ومثلثات من ثلاث زوايا.","simple":"فرجار ومثلث رسم للشاشة.","deep":"<code>fillCircle(cx, cy, r, colour)</code> تستخدم المركز لا الزاوية. والمثلثات تأخذ <code>(x0, y0, x1, y1, x2, y2, colour)</code>. وكلها مبنية من خطوط أفقية سريعة على مخزن الإطار عندنا."},"gfx-line":{"short":"ترسم خطًّا مستقيمًا بين نقطتين، أو خطًّا أفقيًا أو عموديًا سريعًا.","simple":"مسطرة وقلم رصاص. والخطوط «السريعة» تسير مستقيمة أفقيًا أو عموديًا فقط، وهي أسرع بكثير.","deep":"<code>drawLine(x0, y0, x1, y1, c)</code> تستخدم خوارزمية Bresenham، بكسلًا بكسلًا. و<code>drawFastHLine(x, y, w, c)</code> تملأ سلسلة من البكسلات بـ <code>std::fill_n</code> واحدة على مخزن الإطار عندنا، لذا تستخدمها الفواصل والأشرطة."},"gfx-cursor":{"short":"<code>setCursor</code> تحدد أين يبدأ النص؛ ثم <code>fb.print</code> تكتب النص هناك على الشاشة.","simple":"وضع القلم في موضع قبل الكتابة.","deep":"مع الخط المدمج تكون النقطة هي الزاوية العليا اليسرى للنص؛ ومع <code>GFXfont</code> مخصص تكون الطرف الأيسر للخط القاعدي، فيجب أن تكون y أخفض. و<code>print</code> و<code>printf</code> (برموز <code>%</code> نفسها في <code>Serial.printf</code>) تحرّكان المؤشّر وهما تكتبان."},"gfx-text-style":{"short":"اختر لون النص الذي ستطبعه بعد ذلك وحجمه وخطّه.","simple":"اختيار أي قلم وأي قالب خط تستخدم.","deep":"<code>setTextColor(fg)</code> ترسم نصًّا شفافًا؛ و<code>setTextColor(fg, bg)</code> تطلي الخلفية أيضًا (الخط المدمج فقط). و<code>setFont(&amp;FreeSans9pt7b)</code> تختار خطًّا ناعمًا يأتي مع Adafruit GFX (9 pt، عادي)؛ و<code>setFont(nullptr)</code> تعود إلى الخط المدمج 6×8؛ و<code>setTextSize(2)</code> تضاعفه."},"gfx-text-bounds":{"short":"تقيس عرض نص وارتفاعه المحتملين دون رسمه.","simple":"قياس لافتة قبل تعليقها، لتتمكن من توسيطها على الجدار.","deep":"<code>getTextBounds(text, x, y, &amp;x1, &amp;y1, &amp;w, &amp;h)</code> تملأ الصندوق الذي سيغطيه النص بالخط والحجم الحاليين؛ وتُستخدم لتوسيط التسميات ومحاذاتها إلى اليمين."},"gfx-rgb-bitmap":{"short":"تنسخ كتلة كاملة من البكسلات إلى الشاشة دفعة واحدة.","simple":"إدخال صورة منتهية في الإطار، بدل طلائها نقطة نقطة.","deep":"<code>drawRGBBitmap(x, y, pixels, w, h)</code> تبثّ بيانات RGB565 عبر SPI؛ وإطار كامل 320×170 نحو 106 KB، أي نحو 22 ms عند 40 MHz. وهذا هو الحد الأعلى لمعدل الإطارات، ولهذا ترسم المختبرات خارج الشاشة أولًا."},"gfx-rotation":{"short":"تدير صورة الشاشة بخطوات 90°، لتُقرأ باتجاهها الصحيح.","simple":"تدوير إطار صورة من الوضع العمودي إلى الأفقي.","deep":"القيم 0-3 هي 0° و90° و180° و270°. التدوير 1 يجعل اللوحة 170×320 شاشة أفقية 320×170؛ ويتبادل العرض والارتفاع تبعًا لذلك."},"wifi-begin":{"short":"تبدأ الانضمام إلى شبكة Wi-Fi باسمها وكلمة مرورها.","simple":"طرق باب الراوتر بكلمة المرور؛ ويأتي الجواب بعد بضع ثوانٍ.","deep":"تعود فورًا؛ ويحدث الانضمام في مهمة Wi-Fi في الخلفية. يستمع الصنف <code>Connection</code> عندنا إلى الأحداث (اتصل، حصل على IP، انقطع) بدل الانتظار في حلقة. وتمرير <code>nullptr</code> ككلمة مرور ينضم إلى شبكة مفتوحة."},"wifi-mode":{"short":"تختار هل تنضم اللوحة إلى شبكة (محطة station)، أو تنشئ شبكتها (نقطة وصول access point)، أو الاثنين معًا.","simple":"أن تكون ضيفًا في حفلة غيرك، أو تستضيف حفلتك، أو الاثنين في الوقت نفسه.","deep":"<code>WIFI_AP_STA</code> تشغّل الاثنين على راديو واحد، فيتشاركان قناة؛ وتستخدمها بوابة الإعداد لعرض صفحة بينما تجرّب شبكتك. و<code>softAP</code> تبدأ شبكة اللوحة الخاصة، ويمكن الوصول إليها عند <code>192.168.4.1</code> افتراضيًا."},"wifi-info":{"short":"اسأل اتصال Wi-Fi عن التفاصيل: عنوان IP للوحة، وقوة الإشارة، والقناة، وMAC.","simple":"قراءة رقم بيت اللوحة على الشبكة، وكم شريطًا من الإشارة لديها.","deep":"<code>localIP()</code> هو <code>IPAddress</code> (و<code>toString()</code> للنص). و<code>RSSI()</code> بوحدة dBm: نحو -50 ممتازة، وأقل من -80 ضعيفة. وكلها 0 أو فارغة حتى الاتصال."},"wifi-scan":{"short":"تستمع إلى شبكات Wi-Fi القريبة وتسرد أسماءها وإشارتها وأمانها.","simple":"إدارة قرص الراديو لسماع المحطات الموجودة حولك.","deep":"مع <code>async = true</code> تعود فورًا (-1، ما زال المسح جاريًا)؛ استطلع <code>scanComplete()</code> لمعرفة العدد، واقرأ كل مدخل، ثم <code>scanDelete()</code> لتحرير القائمة. ويستغرق المسح بضع ثوانٍ عبر كل القنوات."},"wifi-events":{"short":"تسجّل دالة يستدعيها مشغّل Wi-Fi عندما يحدث شيء: اتصل، أو حصل على IP، أو انقطع.","simple":"أن تطلب من موظف الاستقبال أن يتصل بك عند وصول زائرك، بدل الانتظار في البهو.","deep":"يعمل رد النداء في مهمة أحداث Wi-Fi، لا في <code>loop()</code>، فيجب أن يضبط أعلامًا فقط؛ و<code>loop()</code> تقوم بالعمل الحقيقي. و<code>info</code> تحمل تفاصيل مثل سبب الانقطاع."},"mdns":{"short":"تعطي اللوحة اسمًا ودودًا مثل <code>bench.local</code> على شبكتك.","simple":"بطاقة اسم، لتجد الأجهزة الأخرى اللوحة دون معرفة رقمها.","deep":"يجيب DNS متعدد البث (mDNS) عن استعلامات الأسماء على الشبكة المحلية فقط؛ ويدعمه macOS وiOS دون إعداد. و<code>addService(\\"http\\", \\"tcp\\", 80)</code> تعلن أيضًا عن خادم الويب."},"ntp-time":{"short":"تضبط الساعة من خوادم الوقت على الإنترنت، ثم تقرأ التاريخ والوقت المحليين.","simple":"اللوحة بلا ساعة ببطارية، فتسأل الإنترنت «كم الساعة؟» حالما تتصل.","deep":"<code>configTzTime(tz, server1, server2)</code> تضبط المنطقة الزمنية بصيغة POSIX وتبدأ SNTP. و<code>getLocalTime(&amp;tm, timeoutMs)</code> تملأ <code>struct tm</code> وتُرجع <code>false</code> حتى تتم أول مزامنة."},"http-client":{"short":"ترسل طلبات ويب من اللوحة، مثل متصفح صغير: اطلب عنوان URL واحصل على الجواب.","simple":"إرسال رسالة إلى موقع وانتظار ردّه.","deep":"عميل HTTP في Arduino-ESP32 عبر اتصال TCP أو TLS. وتفحص <code>https::get</code> عندنا شهادة الخادم مقابل جذور Mozilla المضمّنة. وتحجب من 0.3 ثانية إلى عدة ثوانٍ، فاستدعها من مهمة عاملة، لا من <code>loop()</code> أبدًا."},"json-document":{"short":"حاوية ArduinoJson لبيانات JSON: املأها مثل قاموس، أو اقرأ واحدة استلمتها.","simple":"صينية ملفات بمجلدات معنونة: <code>doc[\\"heap\\"] = 1234</code> تضع عددًا في المجلد المسمّى heap.","deep":"ArduinoJson 7: يكبر <code>JsonDocument</code> في الكومة heap بحسب الحاجة. و<code>doc[\\"k\\"].to&lt;JsonArray&gt;()</code> تصنع مصفوفات متداخلة؛ و<code>doc[\\"k\\"] | fallback</code> تقرأ بقيمة افتراضية إذا غاب المفتاح أو كان نوعه خاطئًا."},"serialize-json":{"short":"تحوّل <code>JsonDocument</code> إلى نص JSON جاهز للإرسال.","simple":"طباعة محتويات صينية الملفات في رسالة واحدة مرتبة.","deep":"<code>serializeJson(doc, out)</code> تكتب في <code>String</code> أو مخزن <code>char</code> أو مجرى مثل <code>Serial</code>، وتُرجع عدد البايتات المكتوبة."},"deserialize-json":{"short":"تقرأ نص JSON في <code>JsonDocument</code> يمكنك البحث فيه.","simple":"فتح رسالة وفرز محتوياتها في المجلدات المعنونة.","deep":"تُرجع <code>DeserializationError</code> يكون صحيحًا (true) عندما يحدث خطأ (و<code>e.c_str()</code> تقول ما هو). و<code>Filter</code> يُبقي الحقول التي تحتاجها فقط، مما يوفّر كثيرًا من RAM مع ردود الطقس الكبيرة."},"async-web-server":{"short":"خادم ويب على اللوحة: يفتح هاتفك أو حاسوبك صفحة أو واجهة API، وتجيب اللوحة.","simple":"واجهة محل صغيرة: لكل عنوان (<code>/api/card</code>) موظف يعرف ماذا يرد.","deep":"يجيب ESPAsyncWebServer في مهمة الشبكة الخاصة به، فلا تنتظر الشاشة والقارئ أبدًا. و<code>server_.on(path, HTTP_GET, handler)</code> تسجّل مسارًا؛ ويجب أن تكون المعالجات سريعة وألا تحجب، فيُوضع العمل الثقيل في طابور إلى مهمة أخرى."},"async-request":{"short":"طلب ويب واحد وارد: ما الذي طُلب، وكيف يُجاب عنه.","simple":"الزبون عند واجهة المحل: تقرأ طلبه وتسلّمه ردًّا.","deep":"تستلمه المعالجات كمؤشّر، ولذلك <code>req-&gt;send(200, \\"application/json\\", body)</code>. و<code>hasParam</code>/<code>getParam</code> تقرآن حقول الاستعلام أو النموذج. ويجب أن يحصل كل طلب على <code>send</code> واحدة بالضبط."},"async-web-socket":{"short":"خط حي ثنائي الاتجاه مع المتصفح، فتدفع اللوحة التحديثات لحظة حدوث شيء.","simple":"مكالمة هاتفية بدل الرسائل: يبقى الخط مفتوحًا ويستطيع أي طرف الكلام في أي وقت.","deep":"يُركَّب على خادم الويب عند مسار مثل <code>/ws</code>. و<code>textAll</code> ترسل إلى كل متصفح متصل؛ و<code>onEvent</code> تسمع الاتصالات والانقطاعات والرسائل. استدعِ <code>cleanupClients()</code> بين الحين والآخر لإسقاط الاتصالات التي ذهبت."},"nimble-device":{"short":"الباب الأمامي لبلوتوث LE: يبدأ حزمة الراديو ويوزّع الخوادم والماسحات والعملاء.","simple":"مكتب استقبال بلوتوث: قل مرحبًا مرة واحدة بـ <code>init</code>، ثم اطلب منه ما تحتاجه.","deep":"NimBLE-Arduino، حزمة BLE أخف من Bluedroid. دواله <code>static</code>، فتُستدعى بالشكل <code>NimBLEDevice::...</code> دون كائن. و<code>init(name)</code> تضبط الاسم المُعلَن؛ و<code>setPower</code> تضبط قدرة الإرسال بوحدة dBm."},"nimble-server":{"short":"قائمة بلوتوث الخاصة بالوحة: تجمّع الخدمات الخصائص، وهي قيم صغيرة يستطيع الهاتف قراءتها أو كتابتها أو الاشتراك فيها.","simple":"لوحة إعلانات بخانات معنونة: يقترب هاتف، فيقرأ خانة درجة الحرارة، أو يثبّت رسالة في خانة الرسائل.","deep":"GATT: تحمل الخدمة (UUID) خصائص، لكل منها UUID وخصائص مثل <code>READ | WRITE | NOTIFY</code> وقيمة حتى حجم MTU. و<code>notify()</code> تدفع قيمة جديدة إلى الهواتف المشتركة دون أن تُطلب."},"nimble-advertising":{"short":"تجعل اللوحة تصيح «أنا هنا!» عدة مرات في الثانية، لتراها الهواتف وتتصل بها.","simple":"منارة: ومضات قصيرة على فترات منتظمة يستطيع أي قريب رؤيتها.","deep":"تحمل حزمة إعلان قديمة 31 بايتًا على الأكثر (الاسم والأعلام ومعرّفات UUID للخدمات وبيانات المصنّع)، مع 31 أخرى في رد المسح."},"nimble-scan":{"short":"تستمع إلى أجهزة بلوتوث أخرى تعلن عن نفسها قريبًا وتبلّغ عن كل جهاز تجده.","simple":"مراقبة الساحل بحثًا عن ومضات المنارات وتدوين كل واحدة ترها.","deep":"لكل <code>NimBLEAdvertisedDevice</code> عنوان وRSSI وحمولة. والمسح النشط يطلب ردود المسح أيضًا. تعمل ردود النداء في مهمة مضيف NimBLE، فسلّم النتائج إلى <code>loop()</code> بدل الرسم هناك."},"nimble-client":{"short":"اللوحة في دور الزائر: تتصل بجهاز بلوتوث آخر وتقرأ قيمه أو تكتبها.","simple":"الاقتراب من لوحة إعلانات غيرك بدل استضافة لوحتك.","deep":"الدور المركزي. اتصل، واكتشف الخدمات (<code>getServices(true)</code>)، ثم اقرأ الخصائص البعيدة أو اكتب فيها أو اشترك. الاتصال والاكتشاف يحجبان، لذا ينفّذهما B8 في مهمة عاملة."},"nimble-conn-info":{"short":"تفاصيل اتصال بلوتوث واحد: من المتصل، وكيف هو مؤمَّن، وكم يمكن أن يبلغ حجم الحزمة.","simple":"شارة الزائر: الاسم، وهل أبرز هويته، وكم يستطيع أن يحمل دفعة واحدة.","deep":"تُمرَّر إلى ردود نداء مثل <code>onConnect</code> و<code>onAuthenticationComplete</code>: عنوان النظير، ومقبض الاتصال، وMTU، وهل الرابط مشفّر وموثَّق ومقترن (bonded)."},"nimble-callbacks":{"short":"أصناف ترثها لتسمع عن أحداث بلوتوث: الاتصال والانقطاع والكتابة والقراءة.","simple":"ترك رقم هاتفك عند مكتب الاستقبال: «اتصل بي عندما يصل أحد».","deep":"تجاوز فقط الدوال <code>virtual</code> التي تحتاجها (<code>onConnect</code> و<code>onWrite</code>...)، ثم سجّل الكائن بـ <code>setCallbacks</code>. تعمل في مهمة مضيف NimBLE، فأبقِها قصيرة وآمنة بين الخيوط."},"nimble-security":{"short":"تقرر كيف يُؤمَّن رابط بلوتوث: الاقتران ومفاتيح المرور والروابط المحفوظة.","simple":"سياسة الباب: أدخل أي أحد، أو اطلب رمزًا، أو لا تُدخل إلا الأصدقاء الذين قابلتهم من قبل.","deep":"<code>setSecurityAuth(bond, mitm, sc)</code> تطلب الاقتران (bonding) والحماية من الوسيط (man-in-the-middle) وLE Secure Connections؛ وتقرر قدرة الإدخال/الإخراج هل يُعرض مفتاح مرور أو مقارنة نعم/لا. وتُخزَّن الروابط في NVS وتبقى بعد إعادة التشغيل."},"ble-note":{"short":"اختصار هذا المشروع لإضافة سطر إلى سجل نشاط مختبرات بلوتوث.","simple":"تدوينة سريعة في دفتر المختبر تعرضها الشاشة والسجل التسلسلي معًا.","deep":"ماكرو من <code>kit/lib/ble-kit/src/ble_link.h</code> يتوسّع إلى <code>::ble::activity().add(::ble::Act::kind, ...)</code>: مدخل بنمط printf في مخزن حلقي يحرسه مقطع حرج، فتستطيع ردود النداء في مهمة NimBLE الكتابة بأمان."},"i2s-channel":{"short":"تُعدّ قناة صوت I2S إلى ميكروفون رقمي أو مضخّم سماعة.","simple":"مدّ سير ناقل للصوت: ساعة تضبط الإيقاع، ورقم واحد يركب مع كل عيّنة.","deep":"مشغّل I2S في ESP-IDF 5: <code>i2s_new_channel</code> تنشئ قناتَي TX و/أو RX، و<code>i2s_channel_init_std_mode</code> تضبط معدل العيّنات وعرض البتّات والأطراف (صيغة I2S القياسية Philips)، و<code>i2s_channel_enable</code> تبدأ الساعات وDMA."},"i2s-read-write":{"short":"تأخذ عيّنات من الميكروفون، أو تسلّم عيّنات إلى السماعة، عبر قناة I2S.","simple":"التقاط طرود من السير الناقل، أو وضعها عليه.","deep":"<code>i2s_channel_read(handle, buf, bytes, &amp;got, timeoutMs)</code> تنسخ من مخازن DMA وتنتظر إذا لم يكن أي منها جاهزًا. وتنتظر الكتابة ما دام DMA ممتلئًا، فتعمل مهمة السماعة بالضبط بسرعة تشغيل الصوت."}}`),topics:{basics:{title:`لبنات البناء`,blurb:`الرموز الصغيرة التي تجري الحسابات والمقارنات والخيارات في كل سطر.`},types:{title:`أنواع القيم`,blurb:`الأعداد الصحيحة والعشرية والنص ونعم/لا: ما الذي يستطيع كل صندوق حمله.`},flow:{title:`اتخاذ القرارات والتكرار`,blurb:`كيف يختار الكود مسارًا، ويكرر، وينهي عملًا.`},functions:{title:`الدوال`,blurb:`وصفات مسمّاة يستطيع الكود تشغيلها، من setup() وloop() إلى اللامدا الصغيرة.`},memory:{title:`الذاكرة وconst`,blurb:`أين تعيش القيم، وكيف تشير إليها، وكيف تمنعها من التغيّر.`},classes:{title:`أنواع تبنيها`,blurb:`البنى والأصناف وenum وفضاءات الأسماء: أنواعك الخاصة من الأشياء.`},modern:{title:`C++ الحديثة`,blurb:`ثوابت وقت الترجمة والقوالب والتحويلات ومساعدات المكتبة القياسية.`},preprocessor:{title:`قبل الترجمة`,blurb:`أسطر تبدأ بـ # تعيد ترتيب الكود قبل أن يقرأه المترجم.`},arduino:{title:`أساسيات Arduino`,blurb:`الأطراف والتوقيت والطباعة التسلسلية والنص: عدّة Arduino اليومية.`},esp:{title:`رقاقة ESP32`,blurb:`التسجيل والذاكرة والمؤقتات والتخزين الخاصة بهذه الرقاقة.`},rtos:{title:`فعل شيئين في وقت واحد`,blurb:`مهام FreeRTOS والطوابير والأقفال التي تتيح للوحة تعدد المهام بأمان.`},libraries:{title:`المكتبات`,blurb:`مساعدات الشاشة وWi-Fi وخادم الويب وJSON وبلوتوث والصوت التي تستخدمها المختبرات.`}}};export{e as default};
